const GUESS_NUMBER_HTML = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no" />
<style>
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; }
  body {
    background: #1a1a2e; color: #ffffff;
    font-family: -apple-system, "Helvetica Neue", Arial, sans-serif;
    display: flex; align-items: center; justify-content: center;
    padding: 20px; text-align: center;
  }
  .wrap { width: 100%; max-width: 420px; }
  h1 { font-size: 22px; margin: 0 0 8px; }
  p { color: #aaa; font-size: 13px; margin: 0 0 18px; }
  input {
    width: 100%; padding: 12px; font-size: 18px; text-align: center;
    background: #2d2d44; color: #fff; border: 1px solid #3a3a58; border-radius: 10px;
  }
  button {
    width: 100%; margin-top: 12px; padding: 13px; font-size: 16px; font-weight: 700;
    background: #6c63ff; color: #fff; border: none; border-radius: 10px;
  }
  #msg { min-height: 24px; margin-top: 16px; font-size: 15px; font-weight: 600; }
  #meta { color: #888; font-size: 12px; margin-top: 8px; }
</style>
</head>
<body>
<div class="wrap">
  <h1>猜数字</h1>
  <p>我心里有个 1 到 100 之间的整数，来猜猜看。</p>
  <input id="guess" type="number" inputmode="numeric" placeholder="输入数字" />
  <button id="submit">提交</button>
  <div id="msg"></div>
  <div id="meta"></div>
</div>
<script>
  var answer = Math.floor(Math.random() * 100) + 1;
  var tries = 0;
  var input = document.getElementById('guess');
  var msg = document.getElementById('msg');
  var meta = document.getElementById('meta');
  function reset() {
    answer = Math.floor(Math.random() * 100) + 1;
    tries = 0;
    input.value = '';
    msg.textContent = '';
    meta.textContent = '';
    input.focus();
  }
  function submit() {
    var value = parseInt(input.value, 10);
    if (!value || value < 1 || value > 100) {
      msg.textContent = '请输入 1 到 100 之间的整数';
      return;
    }
    tries += 1;
    if (value === answer) {
      msg.textContent = '答对了！共猜了 ' + tries + ' 次';
      meta.textContent = '再次点击「提交」或输入新数字将重新开始';
      answer = -1;
    } else if (value < answer) {
      msg.textContent = '太小了';
    } else {
      msg.textContent = '太大了';
    }
    input.value = '';
    if (answer === -1) {
      setTimeout(reset, 1200);
    }
  }
  document.getElementById('submit').addEventListener('click', submit);
  input.addEventListener('keydown', function (event) {
    if (event.key === 'Enter' || event.keyCode === 13) submit();
  });
</script>
</body>
</html>`;
const SNAKE_HTML = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no" />
<style>
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; }
  body {
    background: #1a1a2e; color: #ffffff;
    font-family: -apple-system, "Helvetica Neue", Arial, sans-serif;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    padding: 16px;
  }
  h1 { font-size: 20px; margin: 0 0 6px; }
  #score { color: #aaa; font-size: 13px; margin-bottom: 12px; }
  canvas { background: #20203a; border-radius: 12px; touch-action: none; }
  .pad {
    display: grid; margin-top: 16px;
    grid-template-columns: repeat(3, min(60px, 22vw));
    grid-template-rows: repeat(3, min(60px, 22vw));
    gap: 8px; justify-content: center;
  }
  .pad button {
    width: 100%; height: 100%; font-size: 22px; line-height: 1;
    display: flex; align-items: center; justify-content: center;
    background: #2d2d44; color: #fff; border: 1px solid #3a3a58; border-radius: 12px;
    padding: 0;
  }
  .pad .up { grid-column: 2; grid-row: 1; }
  .pad .left { grid-column: 1; grid-row: 2; }
  .pad .right { grid-column: 3; grid-row: 2; }
  .pad .down { grid-column: 2; grid-row: 3; }
  #restart {
    margin-top: 8px; padding: 10px 20px; background: #6c63ff; color: #fff;
    border: none; border-radius: 10px; font-size: 14px; font-weight: 700;
  }
</style>
</head>
<body>
<h1>贪吃蛇</h1>
<div id="score">得分：0</div>
<canvas id="board" width="300" height="300"></canvas>
<div class="pad">
  <button class="up" data-dir="up" aria-label="上">▲</button>
  <button class="left" data-dir="left" aria-label="左">◀</button>
  <button class="right" data-dir="right" aria-label="右">▶</button>
  <button class="down" data-dir="down" aria-label="下">▼</button>
</div>
<button id="restart">重新开始</button>
<script>
  var canvas = document.getElementById('board');
  var ctx = canvas.getContext('2d');
  var CELL = 15;
  var COUNT = canvas.width / CELL;
  var snake, dir, nextDir, food, score, timer, alive;
  var scoreEl = document.getElementById('score');

  function placeFood() {
    var spot;
    do {
      spot = { x: Math.floor(Math.random() * COUNT), y: Math.floor(Math.random() * COUNT) };
    } while (snake.some(function (part) { return part.x === spot.x && part.y === spot.y; }));
    food = spot;
  }

  function start() {
    snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = dir;
    score = 0;
    alive = true;
    scoreEl.textContent = '得分：0';
    placeFood();
    if (timer) clearInterval(timer);
    timer = setInterval(tick, 140);
    draw();
  }

  function tick() {
    if (!alive) return;
    dir = nextDir;
    var head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };
    if (head.x < 0 || head.y < 0 || head.x >= COUNT || head.y >= COUNT) return gameOver();
    if (snake.some(function (part) { return part.x === head.x && part.y === head.y; })) return gameOver();
    snake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
      score += 1;
      scoreEl.textContent = '得分：' + score;
      placeFood();
    } else {
      snake.pop();
    }
    draw();
  }

  function gameOver() {
    alive = false;
    clearInterval(timer);
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 20px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('游戏结束', canvas.width / 2, canvas.height / 2 - 10);
    ctx.font = '14px sans-serif';
    ctx.fillStyle = '#aaa';
    ctx.fillText('得分 ' + score, canvas.width / 2, canvas.height / 2 + 16);
  }

  function draw() {
    ctx.fillStyle = '#20203a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ff5a5f';
    ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);
    snake.forEach(function (part, index) {
      ctx.fillStyle = index === 0 ? '#8b85ff' : '#6c63ff';
      ctx.fillRect(part.x * CELL + 1, part.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function setDir(name) {
    var table = {
      up: { x: 0, y: -1 },
      down: { x: 0, y: 1 },
      left: { x: -1, y: 0 },
      right: { x: 1, y: 0 }
    };
    var candidate = table[name];
    if (!candidate) return;
    if (candidate.x === -dir.x && candidate.y === -dir.y) return;
    nextDir = candidate;
  }

  Array.prototype.forEach.call(document.querySelectorAll('button[data-dir]'), function (button) {
    button.addEventListener('click', function () { setDir(button.getAttribute('data-dir')); });
  });
  document.getElementById('restart').addEventListener('click', start);
  document.addEventListener('keydown', function (event) {
    var map = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right' };
    if (map[event.key]) { event.preventDefault(); setDir(map[event.key]); }
  });

  var startX = 0, startY = 0;
  canvas.addEventListener('touchstart', function (event) {
    var touch = event.changedTouches[0];
    startX = touch.clientX;
    startY = touch.clientY;
  });
  canvas.addEventListener('touchend', function (event) {
    var touch = event.changedTouches[0];
    var dx = touch.clientX - startX;
    var dy = touch.clientY - startY;
    if (Math.abs(dx) < 20 && Math.abs(dy) < 20) return;
    setDir(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up'));
  });
  document.addEventListener('touchmove', function (event) { event.preventDefault(); }, { passive: false });

  start();
</script>
</body>
</html>`;
const BREAKOUT_HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=no, viewport-fit=cover\">\n    <title>打砖块 - 无尽冒险</title>\n    <style>\n        :root {\n            --safe-bottom: env(safe-area-inset-bottom, 10px);\n        }\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n            -webkit-tap-highlight-color: transparent;\n            -webkit-user-select: none;\n            user-select: none;\n            -webkit-touch-callout: none;\n        }\n\n        body {\n            background: #0a0a1a;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            height: 100vh;\n            height: 100dvh;\n            overflow: hidden;\n            font-family: 'PingFang SC', 'Helvetica Neue', 'Arial', sans-serif;\n            touch-action: manipulation;\n            -webkit-overflow-scrolling: none;\n            position: fixed;\n            width: 100%;\n            top: 0;\n            left: 0;\n        }\n\n        #game-container {\n            position: relative;\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n            justify-content: center;\n            width: 100%;\n            max-width: 460px;\n            padding: 8px;\n            padding-bottom: var(--safe-bottom);\n        }\n\n        canvas {\n            display: block;\n            border-radius: 16px;\n            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5), 0 0 0 2px rgba(255, 255, 255, 0.08),\n                0 0 60px rgba(100, 140, 255, 0.15);\n            background: #0d0d24;\n            max-width: 100%;\n            touch-action: none;\n        }\n    </style>\n</head>\n<body>\n    <div id=\"game-container\">\n        <canvas id=\"gameCanvas\"></canvas>\n    </div>\n\n    <script>\n        (function() {\n            const canvas = document.getElementById('gameCanvas');\n            const ctx = canvas.getContext('2d');\n\n            // ============ 响应式Canvas设置 ============\n            const MAX_WIDTH = 420;\n            const MAX_HEIGHT = 720;\n            const ASPECT_RATIO = MAX_WIDTH / MAX_HEIGHT;\n\n            function resizeCanvas() {\n                const vw = window.innerWidth;\n                const vh = window.innerHeight;\n                let w = Math.min(vw * 0.94, MAX_WIDTH);\n                let h = Math.min(vh * 0.78, MAX_HEIGHT);\n                if (w / h > ASPECT_RATIO) {\n                    w = h * ASPECT_RATIO;\n                } else {\n                    h = w / ASPECT_RATIO;\n                }\n                w = Math.floor(w);\n                h = Math.floor(h);\n                canvas.width = w;\n                canvas.height = h;\n                canvas.style.width = w + 'px';\n                canvas.style.height = h + 'px';\n            }\n\n            window.addEventListener('resize', () => {\n                resizeCanvas();\n                if (typeof updateGameDimensions === 'function') updateGameDimensions();\n            });\n            window.addEventListener('orientationchange', () => {\n                setTimeout(() => {\n                    resizeCanvas();\n                    if (typeof updateGameDimensions === 'function') updateGameDimensions();\n                }, 300);\n            });\n            resizeCanvas();\n\n            // ============ 游戏参数（动态更新） ============\n            let W, H;\n            let PADDLE_Y, PADDLE_W, PADDLE_H, PADDLE_BASE_W;\n            let BALL_RADIUS;\n            let BRICK_ROWS, BRICK_COLS;\n            let BRICK_W, BRICK_H, BRICK_GAP, BRICK_OFFSET_X, BRICK_OFFSET_Y;\n            let BALL_SPEED;\n            let POWERUP_SIZE;\n            let POWERUP_SPEED;\n\n            function updateGameDimensions() {\n                W = canvas.width;\n                H = canvas.height;\n                PADDLE_BASE_W = Math.floor(W * 0.22);\n                PADDLE_W = PADDLE_BASE_W;\n                PADDLE_H = Math.floor(H * 0.018);\n                PADDLE_Y = H - Math.floor(H * 0.09);\n                BALL_RADIUS = Math.floor(W * 0.018);\n                BRICK_COLS = 8;\n                BRICK_GAP = Math.floor(W * 0.012);\n                const totalGap = BRICK_GAP * (BRICK_COLS + 1);\n                BRICK_W = Math.floor((W - totalGap) / BRICK_COLS);\n                BRICK_H = Math.floor(H * 0.032);\n                BRICK_OFFSET_X = BRICK_GAP;\n                BRICK_OFFSET_Y = Math.floor(H * 0.11);\n                BALL_SPEED = Math.floor(H * 0.55);\n                POWERUP_SIZE = Math.floor(W * 0.045);\n                POWERUP_SPEED = Math.floor(H * 0.28);\n            }\n            updateGameDimensions();\n\n            // ============ 游戏状态 ============\n            const STATE = {\n                MENU: 'menu',\n                PLAYING: 'playing',\n                LEVEL_CLEAR: 'levelClear',\n                GAME_OVER: 'gameOver',\n                PAUSED: 'paused',\n            };\n\n            let gameState = STATE.MENU;\n            let currentLevel = 1;\n            let score = 0;\n            let lives = 3;\n            let balls = [];\n            let bricks = [];\n            let powerUps = [];\n            let particles = [];\n            let paddleX = W / 2;\n            let prevPaddleX = W / 2;\n            let paddleVelocity = 0;\n            let paddleWidthMultiplier = 1;\n            let paddleWidthTimer = 0;\n            let slowMotionTimer = 0;\n            let pierceTimer = 0;\n            let ballWaiting = true;\n            let shakeTimer = 0;\n            let shakeIntensity = 0;\n            let comboCount = 0;\n            let comboTimer = 0;\n            let maxBalls = 27;\n            let totalBallsEver = 0;\n            let levelTransitionTimer = 0;\n            let flashAlpha = 0;\n\n            // ============ 输入处理 ============\n            let touchActive = false;\n            let touchX = W / 2;\n\n            function getEventX(e) {\n                const rect = canvas.getBoundingClientRect();\n                const clientX = e.touches ? e.touches[0].clientX : e.clientX;\n                const scaleX = W / rect.width;\n                return (clientX - rect.left) * scaleX;\n            }\n\n            canvas.addEventListener('touchstart', function(e) {\n                e.preventDefault();\n                touchActive = true;\n                touchX = getEventX(e);\n                if (ballWaiting && gameState === STATE.PLAYING) launchBall();\n                if (gameState === STATE.MENU) startGame();\n                if (gameState === STATE.GAME_OVER) restartGame();\n                if (gameState === STATE.LEVEL_CLEAR) advanceLevel();\n            }, { passive: false });\n\n            canvas.addEventListener('touchmove', function(e) {\n                e.preventDefault();\n                if (touchActive) touchX = getEventX(e);\n            }, { passive: false });\n\n            canvas.addEventListener('touchend', function(e) {\n                e.preventDefault();\n                touchActive = false;\n            }, { passive: false });\n\n            canvas.addEventListener('touchcancel', function() {\n                touchActive = false;\n            });\n\n            canvas.addEventListener('mousemove', function(e) {\n                if (!touchActive) touchX = getEventX(e);\n            });\n\n            canvas.addEventListener('click', function(e) {\n                if (touchActive) return;\n                if (ballWaiting && gameState === STATE.PLAYING) launchBall();\n                if (gameState === STATE.MENU) startGame();\n                if (gameState === STATE.GAME_OVER) restartGame();\n                if (gameState === STATE.LEVEL_CLEAR) advanceLevel();\n            });\n\n            // ============ 砖块系统 ============\n            const BRICK_TYPE = {\n                NORMAL: 'normal',\n                GOLD: 'gold',\n                STEEL: 'steel',   // 已废弃，全部转为普通砖\n                BOMB: 'bomb',\n            };\n\n            function createBrick(col, row, type = BRICK_TYPE.NORMAL, forcedPowerUp = null) {\n                // ★★★ 修复：强制将钢砖转换为普通砖，避免卡死问题 ★★★\n                if (type === BRICK_TYPE.STEEL) {\n                    type = BRICK_TYPE.NORMAL;\n                }\n\n                const x = BRICK_OFFSET_X + col * (BRICK_W + BRICK_GAP);\n                const y = BRICK_OFFSET_Y + row * (BRICK_H + BRICK_GAP);\n                const colors = [\n                    '#ff5e5e', '#ff8c42', '#ffc048', '#ffe74c',\n                    '#7fff5e', '#5ec8ff', '#b07fff', '#ff6eb4'\n                ];\n                let color = colors[row % colors.length];\n                let hp = 1;\n                let maxHp = 1;\n                let dropsPowerUp = false;\n                let forcedDrop = forcedPowerUp;\n                let isBomb = false;\n\n                if (type === BRICK_TYPE.GOLD) {\n                    color = '#ffd700';\n                    dropsPowerUp = true;\n                } else if (type === BRICK_TYPE.BOMB) {\n                    color = '#ff3333';\n                    isBomb = true;\n                }\n\n                return {\n                    x, y, w: BRICK_W, h: BRICK_H,\n                    col, row, type, color, originalColor: color,\n                    hp, maxHp, alive: true,\n                    dropsPowerUp, forcedDrop, isBomb,\n                    respawnTimer: 0, respawnDelay: 0,\n                    glowPhase: Math.random() * Math.PI * 2,\n                };\n            }\n\n            function generateLevel(level) {\n                bricks = [];\n                if (level === 1) {\n                    BRICK_ROWS = 5;\n                    for (let row = 0; row < BRICK_ROWS; row++) {\n                        for (let col = 0; col < BRICK_COLS; col++) {\n                            let type = BRICK_TYPE.NORMAL;\n                            if (row === 1 && col === 3) type = BRICK_TYPE.GOLD;\n                            if (row === 2 && col === 5) type = BRICK_TYPE.GOLD;\n                            // 原本的钢砖已转为普通砖，不必特殊处理\n                            if (row === 3 && col === 2) type = BRICK_TYPE.NORMAL; \n                            if (row === 0 && col === 6) type = BRICK_TYPE.BOMB;\n                            if (row === 3 && col === 7) type = BRICK_TYPE.BOMB;\n                            bricks.push(createBrick(col, row, type));\n                        }\n                    }\n                } else if (level === 2) {\n                    BRICK_ROWS = 7;\n                    for (let row = 0; row < BRICK_ROWS; row++) {\n                        for (let col = 0; col < BRICK_COLS; col++) {\n                            let type = BRICK_TYPE.NORMAL;\n                            if (row === 0 && col === 2) type = BRICK_TYPE.GOLD;\n                            if (row === 1 && col === 6) type = BRICK_TYPE.GOLD;\n                            if (row === 2 && col === 4) type = BRICK_TYPE.GOLD;\n                            // 原钢砖 -> 普通\n                            if (row === 3 && col === 1) type = BRICK_TYPE.NORMAL;\n                            if (row === 4 && col === 7) type = BRICK_TYPE.NORMAL;\n                            if (row === 6 && col === 0) type = BRICK_TYPE.NORMAL;\n                            if (row === 5 && col === 3) type = BRICK_TYPE.BOMB;\n                            if (row === 0 && col === 5) type = BRICK_TYPE.BOMB;\n                            if (row === 6 && col === 7) type = BRICK_TYPE.GOLD;\n                            bricks.push(createBrick(col, row, type));\n                        }\n                    }\n                } else if (level === 3) {\n                    BRICK_ROWS = 6;\n                    for (let row = 0; row < BRICK_ROWS; row++) {\n                        for (let col = 0; col < BRICK_COLS; col++) {\n                            let type = BRICK_TYPE.NORMAL;\n                            let forcedDrop = null;\n                            if (row === 0 && col === 3) {\n                                type = BRICK_TYPE.GOLD;\n                                forcedDrop = 'split';\n                            }\n                            if (row === 0 && col === 6) type = BRICK_TYPE.GOLD;\n                            // 原钢砖 -> 普通\n                            if (row === 1 && col === 1) type = BRICK_TYPE.NORMAL;\n                            if (row === 1 && col === 5) type = BRICK_TYPE.BOMB;\n                            if (row === 2 && col === 7) type = BRICK_TYPE.GOLD;\n                            if (row === 3 && col === 0) type = BRICK_TYPE.NORMAL;\n                            if (row === 3 && col === 4) type = BRICK_TYPE.BOMB;\n                            if (row === 4 && col === 2) type = BRICK_TYPE.GOLD;\n                            if (row === 4 && col === 6) type = BRICK_TYPE.NORMAL;\n                            if (row === 5 && col === 3) type = BRICK_TYPE.BOMB;\n                            if (row === 5 && col === 5) type = BRICK_TYPE.GOLD;\n                            bricks.push(createBrick(col, row, type, forcedDrop));\n                        }\n                    }\n                }\n                // 确保第3关第一行至少有分裂道具砖\n                if (level === 3) {\n                    let hasSplitBrick = bricks.some(b => b.row === 0 && b.forcedDrop === 'split' && b.alive);\n                    if (!hasSplitBrick) {\n                        for (let b of bricks) {\n                            if (b.row === 0 && b.type === BRICK_TYPE.GOLD && b.alive) {\n                                b.forcedDrop = 'split';\n                                hasSplitBrick = true;\n                                break;\n                            }\n                        }\n                        if (!hasSplitBrick) {\n                            for (let b of bricks) {\n                                if (b.row === 0 && b.col === 3 && b.alive) {\n                                    b.type = BRICK_TYPE.GOLD;\n                                    b.color = '#ffd700';\n                                    b.originalColor = '#ffd700';\n                                    b.dropsPowerUp = true;\n                                    b.forcedDrop = 'split';\n                                    break;\n                                }\n                            }\n                        }\n                    }\n                }\n            }\n\n            function respawnBrick(brick) {\n                brick.alive = true;\n                brick.hp = brick.maxHp;\n                brick.color = brick.originalColor;\n                brick.respawnTimer = 0;\n                brick.respawnDelay = 0;\n                if (brick.type === BRICK_TYPE.GOLD) brick.dropsPowerUp = true;\n            }\n\n            // ============ 道具系统 ============\n            const POWERUP_TYPE = {\n                SPLIT: 'split',\n                WIDE: 'wide',\n                SLOW: 'slow',\n                LIFE: 'life',\n                PIERCE: 'pierce',\n            };\n\n            function createPowerUp(x, y, type) {\n                return { x, y, type, size: POWERUP_SIZE, vy: POWERUP_SPEED, alive: true, glowPhase: 0 };\n            }\n\n            function getPowerUpColor(type) {\n                switch (type) {\n                    case POWERUP_TYPE.SPLIT: return '#00ff88';\n                    case POWERUP_TYPE.WIDE: return '#4da6ff';\n                    case POWERUP_TYPE.SLOW: return '#ffe066';\n                    case POWERUP_TYPE.LIFE: return '#ff5555';\n                    case POWERUP_TYPE.PIERCE: return '#ff9900';\n                    default: return '#ffffff';\n                }\n            }\n\n            function getPowerUpIcon(type) {\n                switch (type) {\n                    case POWERUP_TYPE.SPLIT: return '⊕';\n                    case POWERUP_TYPE.WIDE: return '↔';\n                    case POWERUP_TYPE.SLOW: return '⏱';\n                    case POWERUP_TYPE.LIFE: return '♥';\n                    case POWERUP_TYPE.PIERCE: return '⚡';\n                    default: return '?';\n                }\n            }\n\n            function getRandomPowerUpType() {\n                const rand = Math.random();\n                if (rand < 0.22) return POWERUP_TYPE.SPLIT;\n                if (rand < 0.47) return POWERUP_TYPE.WIDE;\n                if (rand < 0.67) return POWERUP_TYPE.SLOW;\n                if (rand < 0.82) return POWERUP_TYPE.LIFE;\n                return POWERUP_TYPE.PIERCE;\n            }\n\n            function spawnPowerUp(brick) {\n                const pType = brick.forcedDrop || getRandomPowerUpType();\n                const px = brick.x + brick.w / 2;\n                const py = brick.y + brick.h / 2;\n                powerUps.push(createPowerUp(px, py, pType));\n            }\n\n            function activatePowerUp(type) {\n                switch (type) {\n                    case POWERUP_TYPE.SPLIT: splitAllBalls(); break;\n                    case POWERUP_TYPE.WIDE: paddleWidthMultiplier = 1.7; paddleWidthTimer = 10; break;\n                    case POWERUP_TYPE.SLOW: slowMotionTimer = 8; break;\n                    case POWERUP_TYPE.LIFE: lives = Math.min(lives + 1, 9); spawnHealParticles(paddleX, PADDLE_Y); break;\n                    case POWERUP_TYPE.PIERCE: pierceTimer = 6; break;\n                }\n                flashAlpha = 0.5;\n            }\n\n            function splitAllBalls() {\n                const currentBalls = [...balls];\n                const toAdd = [];\n                for (let ball of currentBalls) {\n                    if (balls.length + toAdd.length >= maxBalls) break;\n                    const speed = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy);\n                    if (speed < 1) continue;\n                    const angle = Math.atan2(ball.vy, ball.vx) + (Math.random() - 0.5) * 0.6;\n                    const newBall = {\n                        x: ball.x,\n                        y: ball.y,\n                        vx: Math.cos(angle) * speed,\n                        vy: Math.sin(angle) * speed,\n                        radius: BALL_RADIUS,\n                        pierceRemaining: ball.pierceRemaining || 0,\n                        trail: [],   // 修复缺失trail导致的崩溃\n                    };\n                    toAdd.push(newBall);\n                }\n                for (let nb of toAdd) {\n                    if (balls.length < maxBalls) {\n                        balls.push(nb);\n                        totalBallsEver++;\n                    }\n                }\n                if (balls.length > maxBalls) balls = balls.slice(0, maxBalls);\n            }\n\n            function spawnHealParticles(x, y) {\n                for (let i = 0; i < 20; i++) {\n                    particles.push({\n                        x, y,\n                        vx: (Math.random() - 0.5) * 180,\n                        vy: (Math.random() - 1) * 200,\n                        life: 0.7 + Math.random() * 0.6,\n                        maxLife: 0.7 + Math.random() * 0.6,\n                        color: '#ff6666',\n                        size: 3 + Math.random() * 5,\n                    });\n                }\n            }\n\n            // ============ 球系统 ============\n            function createBall(x, y, vx, vy) {\n                return {\n                    x, y, vx, vy,\n                    radius: BALL_RADIUS,\n                    pierceRemaining: pierceTimer > 0 ? pierceTimer : 0,\n                    trail: [],\n                };\n            }\n\n            function launchBall() {\n                if (!ballWaiting) return;\n                ballWaiting = false;\n                const angle = -Math.PI / 2 + (Math.random() - 0.5) * 0.9;\n                const speed = BALL_SPEED;\n                balls = [createBall(paddleX, PADDLE_Y - BALL_RADIUS - PADDLE_H / 2, Math.cos(angle) * speed, Math.sin(angle) * speed)];\n                totalBallsEver = 1;\n            }\n\n            function resetBallToPaddle() {\n                balls = [];\n                ballWaiting = true;\n                paddleWidthMultiplier = 1;\n                paddleWidthTimer = 0;\n                slowMotionTimer = 0;\n                pierceTimer = 0;\n            }\n\n            // ============ 粒子系统 ============\n            function spawnBrickParticles(brick) {\n                const cx = brick.x + brick.w / 2;\n                const cy = brick.y + brick.h / 2;\n                const count = brick.isBomb ? 35 : 12;\n                for (let i = 0; i < count; i++) {\n                    const angle = Math.random() * Math.PI * 2;\n                    const speed = 60 + Math.random() * 280;\n                    particles.push({\n                        x: cx, y: cy,\n                        vx: Math.cos(angle) * speed,\n                        vy: Math.sin(angle) * speed - 100,\n                        life: 0.3 + Math.random() * 0.7,\n                        maxLife: 0.3 + Math.random() * 0.7,\n                        color: brick.color,\n                        size: 2 + Math.random() * 5,\n                    });\n                }\n            }\n\n            function spawnExplosionParticles(x, y) {\n                for (let i = 0; i < 25; i++) {\n                    const angle = Math.random() * Math.PI * 2;\n                    const speed = 100 + Math.random() * 350;\n                    particles.push({\n                        x, y,\n                        vx: Math.cos(angle) * speed,\n                        vy: Math.sin(angle) * speed,\n                        life: 0.4 + Math.random() * 0.8,\n                        maxLife: 0.4 + Math.random() * 0.8,\n                        color: Math.random() < 0.5 ? '#ff6600' : '#ffcc00',\n                        size: 3 + Math.random() * 7,\n                    });\n                }\n            }\n\n            // ============ 碰撞处理 ============\n            function ballRectCollision(ball, rect) {\n                const closestX = Math.max(rect.x, Math.min(ball.x, rect.x + rect.w));\n                const closestY = Math.max(rect.y, Math.min(ball.y, rect.y + rect.h));\n                const dx = ball.x - closestX;\n                const dy = ball.y - closestY;\n                return (dx * dx + dy * dy) < (ball.radius * ball.radius);\n            }\n\n            function handleBallBrickCollision(ball, brick) {\n                if (!brick.alive) return false;\n                if (!ballRectCollision(ball, brick)) return false;\n\n                if (ball.pierceRemaining > 0 && !brick.isBomb) {\n                    damageBrick(brick);\n                    return true;\n                }\n\n                const brickCenterX = brick.x + brick.w / 2;\n                const brickCenterY = brick.y + brick.h / 2;\n                const dx = ball.x - brickCenterX;\n                const dy = ball.y - brickCenterY;\n                const overlapX = (ball.radius + brick.w / 2) - Math.abs(dx);\n                const overlapY = (ball.radius + brick.h / 2) - Math.abs(dy);\n\n                if (overlapX < overlapY) {\n                    ball.vx = -ball.vx;\n                    ball.x += Math.sign(dx) * overlapX * 1.1;\n                } else {\n                    ball.vy = -ball.vy;\n                    ball.y += Math.sign(dy) * overlapY * 1.1;\n                }\n                damageBrick(brick);\n                return true;\n            }\n\n            function damageBrick(brick) {\n                brick.hp--;\n                if (brick.hp <= 0) {\n                    destroyBrick(brick);\n                } else {\n                    // 理论上不会进入此分支（钢砖已移除），但保留以防万一\n                    spawnBrickParticles({ x: brick.x, y: brick.y, w: brick.w, h: brick.h, color: '#cccccc', isBomb: false });\n                    shakeTimer = 0.05;\n                    shakeIntensity = 2;\n                }\n            }\n\n            function destroyBrick(brick) {\n                if (!brick.alive) return;\n                brick.alive = false;\n                score += brick.isBomb ? 15 : (brick.type === BRICK_TYPE.GOLD ? 30 : 10);\n                spawnBrickParticles(brick);\n\n                if (brick.isBomb) {\n                    spawnExplosionParticles(brick.x + brick.w / 2, brick.y + brick.h / 2);\n                    shakeTimer = 0.2;\n                    shakeIntensity = 8;\n                    explodeAdjacentBricks(brick);\n                }\n\n                if (brick.dropsPowerUp) spawnPowerUp(brick);\n\n                if (currentLevel === 3) {\n                    brick.respawnDelay = 5 + Math.random() * 10;\n                    brick.respawnTimer = brick.respawnDelay;\n                    if (brick.row === 0 && brick.forcedDrop === 'split') {\n                        brick.respawnDelay = 4 + Math.random() * 6;\n                        brick.respawnTimer = brick.respawnDelay;\n                    }\n                }\n                comboCount++;\n                comboTimer = 1.2;\n                if (comboCount >= 5 && comboCount % 5 === 0) score += comboCount * 2;\n            }\n\n            function explodeAdjacentBricks(bombBrick) {\n                const { col, row } = bombBrick;\n                for (let dr = -1; dr <= 1; dr++) {\n                    for (let dc = -1; dc <= 1; dc++) {\n                        if (dr === 0 && dc === 0) continue;\n                        for (let b of bricks) {\n                            if (b.col === col + dc && b.row === row + dr && b.alive) {\n                                b.hp = 0;\n                                destroyBrick(b);\n                                break;\n                            }\n                        }\n                    }\n                }\n            }\n\n            // ============ 游戏循环 ============\n            let lastTime = performance.now();\n            let dt = 0;\n\n            function gameLoop(timestamp) {\n                dt = Math.min((timestamp - lastTime) / 1000, 0.1);\n                lastTime = timestamp;\n                update(dt);\n                render();\n                requestAnimationFrame(gameLoop);\n            }\n\n            function update(dt) {\n                PADDLE_W = Math.floor(PADDLE_BASE_W * paddleWidthMultiplier);\n\n                prevPaddleX = paddleX;\n                const target = touchActive ? touchX : (touchX || W / 2);\n                paddleX += (target - paddleX) * 0.35;\n                paddleX = Math.max(PADDLE_W / 2, Math.min(W - PADDLE_W / 2, paddleX));\n                paddleVelocity = paddleX - prevPaddleX;\n\n                if (paddleWidthTimer > 0) paddleWidthTimer -= dt;\n                else paddleWidthMultiplier = 1;\n                if (slowMotionTimer > 0) slowMotionTimer -= dt;\n                if (pierceTimer > 0) pierceTimer -= dt;\n                if (shakeTimer > 0) shakeTimer -= dt;\n                if (comboTimer > 0) { comboTimer -= dt; if (comboTimer <= 0) comboCount = 0; }\n                if (flashAlpha > 0) flashAlpha = Math.max(0, flashAlpha - dt * 2.5);\n\n                const speedMultiplier = slowMotionTimer > 0 ? 0.55 : 1;\n                for (let ball of balls) {\n                    if (!ball.trail) ball.trail = [];\n                    if (ball.pierceRemaining > 0 && pierceTimer <= 0) ball.pierceRemaining = Math.max(0, ball.pierceRemaining - dt);\n                    if (pierceTimer > 0) ball.pierceRemaining = pierceTimer;\n\n                    ball.x += ball.vx * dt * speedMultiplier;\n                    ball.y += ball.vy * dt * speedMultiplier;\n\n                    if (ball.x - ball.radius < 0) { ball.x = ball.radius; ball.vx = Math.abs(ball.vx); }\n                    if (ball.x + ball.radius > W) { ball.x = W - ball.radius; ball.vx = -Math.abs(ball.vx); }\n                    if (ball.y - ball.radius < 0) { ball.y = ball.radius; ball.vy = Math.abs(ball.vy); }\n\n                    const paddleLeft = paddleX - PADDLE_W / 2;\n                    const paddleRight = paddleX + PADDLE_W / 2;\n                    if (ball.vy > 0 &&\n                        ball.y + ball.radius >= PADDLE_Y - PADDLE_H / 2 &&\n                        ball.y - ball.radius <= PADDLE_Y + PADDLE_H / 2 &&\n                        ball.x + ball.radius > paddleLeft &&\n                        ball.x - ball.radius < paddleRight) {\n                        ball.y = PADDLE_Y - PADDLE_H / 2 - ball.radius;\n                        const hitPos = (ball.x - paddleX) / (PADDLE_W / 2);\n                        const speed = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy);\n                        const newAngle = -Math.PI / 2 + hitPos * 0.9;\n                        ball.vx = Math.cos(newAngle) * speed + paddleVelocity * 0.4;\n                        ball.vy = Math.sin(newAngle) * speed;\n                        if (Math.abs(ball.vy) < BALL_SPEED * 0.45) ball.vy = Math.sign(ball.vy) * BALL_SPEED * 0.45;\n                        ball.pierceRemaining = pierceTimer > 0 ? pierceTimer : ball.pierceRemaining;\n                        comboCount = 0;\n                        comboTimer = 0;\n                    }\n\n                    if (ball.y - ball.radius > H + 30) ball._lost = true;\n\n                    for (let brick of bricks) {\n                        if (brick.alive) handleBallBrickCollision(ball, brick);\n                    }\n\n                    ball.trail.push({ x: ball.x, y: ball.y, life: 0.15 });\n                    if (ball.trail.length > 8) ball.trail.shift();\n                    for (let t of ball.trail) t.life -= dt;\n                    ball.trail = ball.trail.filter(t => t.life > 0);\n                }\n\n                const lostBalls = balls.filter(b => b._lost);\n                balls = balls.filter(b => !b._lost);\n                if (lostBalls.length > 0 && balls.length === 0) {\n                    lives--;\n                    comboCount = 0;\n                    comboTimer = 0;\n                    if (lives <= 0) {\n                        gameState = STATE.GAME_OVER;\n                        resetBallToPaddle();\n                    } else {\n                        resetBallToPaddle();\n                        shakeTimer = 0.3;\n                        shakeIntensity = 10;\n                    }\n                }\n\n                for (let pu of powerUps) {\n                    pu.y += pu.vy * dt;\n                    pu.glowPhase += dt * 4;\n                    if (pu.y > H + 40) pu.alive = false;\n                    const pLeft = paddleX - PADDLE_W / 2;\n                    const pRight = paddleX + PADDLE_W / 2;\n                    if (pu.y + pu.size / 2 >= PADDLE_Y - PADDLE_H / 2 &&\n                        pu.y - pu.size / 2 <= PADDLE_Y + PADDLE_H / 2 &&\n                        pu.x + pu.size / 2 > pLeft &&\n                        pu.x - pu.size / 2 < pRight &&\n                        pu.alive) {\n                        pu.alive = false;\n                        activatePowerUp(pu.type);\n                        spawnCollectParticles(pu.x, pu.y, getPowerUpColor(pu.type));\n                    }\n                }\n                powerUps = powerUps.filter(pu => pu.alive);\n\n                for (let p of particles) {\n                    p.x += p.vx * dt;\n                    p.y += p.vy * dt;\n                    p.life -= dt;\n                    p.vy += 300 * dt;\n                }\n                particles = particles.filter(p => p.life > 0);\n\n                if (currentLevel === 3) {\n                    for (let brick of bricks) {\n                        if (!brick.alive && brick.respawnTimer > 0) {\n                            brick.respawnTimer -= dt;\n                            if (brick.respawnTimer <= 0) {\n                                respawnBrick(brick);\n                                spawnRespawnParticles(brick);\n                            }\n                        }\n                    }\n                }\n\n                if (currentLevel < 3 && gameState === STATE.PLAYING && bricks.every(b => !b.alive)) {\n                    gameState = STATE.LEVEL_CLEAR;\n                    levelTransitionTimer = 1.5;\n                    resetBallToPaddle();\n                    score += 100;\n                }\n            }\n\n            function spawnCollectParticles(x, y, color) {\n                for (let i = 0; i < 18; i++) {\n                    const angle = Math.random() * Math.PI * 2;\n                    const speed = 80 + Math.random() * 220;\n                    particles.push({\n                        x, y,\n                        vx: Math.cos(angle) * speed,\n                        vy: Math.sin(angle) * speed - 80,\n                        life: 0.3 + Math.random() * 0.5,\n                        maxLife: 0.3 + Math.random() * 0.5,\n                        color, size: 2 + Math.random() * 4,\n                    });\n                }\n            }\n\n            function spawnRespawnParticles(brick) {\n                const cx = brick.x + brick.w / 2;\n                const cy = brick.y + brick.h / 2;\n                for (let i = 0; i < 14; i++) {\n                    const angle = Math.random() * Math.PI * 2;\n                    const speed = 40 + Math.random() * 120;\n                    particles.push({\n                        x: cx, y: cy,\n                        vx: Math.cos(angle) * speed,\n                        vy: Math.sin(angle) * speed - 60,\n                        life: 0.3 + Math.random() * 0.5,\n                        maxLife: 0.3 + Math.random() * 0.5,\n                        color: '#aaddff',\n                        size: 2 + Math.random() * 4,\n                    });\n                }\n            }\n\n            // ============ 渲染 ============\n            function render() {\n                ctx.clearRect(0, 0, W, H);\n\n                let shakeX = 0, shakeY = 0;\n                if (shakeTimer > 0) {\n                    shakeX = (Math.random() - 0.5) * shakeIntensity * (shakeTimer / 0.3);\n                    shakeY = (Math.random() - 0.5) * shakeIntensity * (shakeTimer / 0.3);\n                }\n\n                ctx.save();\n                ctx.translate(shakeX, shakeY);\n\n                // 网格\n                ctx.strokeStyle = 'rgba(255,255,255,0.03)';\n                ctx.lineWidth = 0.5;\n                for (let gx = 28; gx < W; gx += 28) { ctx.beginPath(); ctx.moveTo(gx, 0); ctx.lineTo(gx, H); ctx.stroke(); }\n                for (let gy = 28; gy < H; gy += 28) { ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(W, gy); ctx.stroke(); }\n\n                // 砖块\n                for (let brick of bricks) {\n                    if (!brick.alive) {\n                        if (currentLevel === 3 && brick.respawnTimer > 0) {\n                            const alpha = 0.2 + 0.15 * Math.sin(brick.respawnTimer * 3);\n                            ctx.fillStyle = `rgba(255,255,255,${alpha})`;\n                            ctx.fillRect(brick.x, brick.y, brick.w, brick.h);\n                            const progress = 1 - (brick.respawnTimer / brick.respawnDelay);\n                            ctx.fillStyle = `rgba(200,220,255,${0.5+0.3*Math.sin(brick.respawnTimer*5)})`;\n                            ctx.beginPath();\n                            ctx.arc(brick.x + brick.w / 2, brick.y + brick.h / 2, brick.h * 0.25 * progress, 0, Math.PI * 2);\n                            ctx.fill();\n                        }\n                        continue;\n                    }\n                    if (brick.type === BRICK_TYPE.GOLD) {\n                        brick.glowPhase += dt * 3;\n                        ctx.shadowColor = '#ffd700';\n                        ctx.shadowBlur = 8 + 4 * Math.sin(brick.glowPhase);\n                    }\n                    if (brick.isBomb) {\n                        brick.glowPhase += dt * 5;\n                        ctx.shadowColor = '#ff4400';\n                        ctx.shadowBlur = 6 + 3 * Math.sin(brick.glowPhase);\n                    }\n\n                    const gradient = ctx.createLinearGradient(brick.x, brick.y, brick.x, brick.y + brick.h);\n                    gradient.addColorStop(0, brick.color);\n                    gradient.addColorStop(1, darkenColor(brick.color, 0.4));\n                    ctx.fillStyle = gradient;\n                    ctx.beginPath();\n                    roundRect(ctx, brick.x, brick.y, brick.w, brick.h, 3);\n                    ctx.fill();\n\n                    ctx.fillStyle = 'rgba(255,255,255,0.2)';\n                    ctx.beginPath();\n                    roundRect(ctx, brick.x + 2, brick.y + 1, brick.w - 4, brick.h * 0.4, 2);\n                    ctx.fill();\n\n                    if (brick.isBomb) {\n                        ctx.fillStyle = '#fff';\n                        ctx.font = `${brick.h*0.7}px sans-serif`;\n                        ctx.textAlign = 'center';\n                        ctx.textBaseline = 'middle';\n                        ctx.fillText('💥', brick.x + brick.w / 2, brick.y + brick.h / 2);\n                    }\n                    if (brick.type === BRICK_TYPE.GOLD && !brick.isBomb) {\n                        ctx.fillStyle = '#fff';\n                        ctx.font = `${brick.h*0.6}px sans-serif`;\n                        ctx.textAlign = 'center';\n                        ctx.textBaseline = 'middle';\n                        ctx.fillText('⭐', brick.x + brick.w / 2, brick.y + brick.h / 2);\n                    }\n                    ctx.shadowColor = 'transparent';\n                    ctx.shadowBlur = 0;\n                }\n\n                // 道具\n                for (let pu of powerUps) {\n                    ctx.shadowColor = getPowerUpColor(pu.type);\n                    ctx.shadowBlur = 10 + 5 * Math.sin(pu.glowPhase);\n                    ctx.fillStyle = 'rgba(0,0,0,0.6)';\n                    ctx.beginPath();\n                    ctx.arc(pu.x, pu.y, pu.size / 2 + 2, 0, Math.PI * 2);\n                    ctx.fill();\n                    const puGrad = ctx.createRadialGradient(pu.x - pu.size * 0.2, pu.y - pu.size * 0.2, pu.size * 0.1, pu.x, pu.y, pu.size / 2);\n                    puGrad.addColorStop(0, lightenColor(getPowerUpColor(pu.type), 0.5));\n                    puGrad.addColorStop(1, getPowerUpColor(pu.type));\n                    ctx.fillStyle = puGrad;\n                    ctx.beginPath();\n                    ctx.arc(pu.x, pu.y, pu.size / 2, 0, Math.PI * 2);\n                    ctx.fill();\n                    ctx.fillStyle = '#fff';\n                    ctx.font = `bold ${pu.size*0.55}px sans-serif`;\n                    ctx.textAlign = 'center';\n                    ctx.textBaseline = 'middle';\n                    ctx.fillText(getPowerUpIcon(pu.type), pu.x, pu.y);\n                    ctx.shadowColor = 'transparent';\n                    ctx.shadowBlur = 0;\n                }\n\n                // 球\n                for (let ball of balls) {\n                    if (!ball.trail) ball.trail = [];\n                    for (let i = 0; i < ball.trail.length; i++) {\n                        const t = ball.trail[i];\n                        const alpha = (t.life / 0.15) * 0.5;\n                        ctx.fillStyle = `rgba(255,255,255,${alpha})`;\n                        ctx.beginPath();\n                        ctx.arc(t.x, t.y, ball.radius * (0.3 + 0.7 * (t.life / 0.15)), 0, Math.PI * 2);\n                        ctx.fill();\n                    }\n                    const ballGrad = ctx.createRadialGradient(ball.x - ball.radius * 0.25, ball.y - ball.radius * 0.25, ball.radius * 0.1, ball.x, ball.y, ball.radius);\n                    if (ball.pierceRemaining > 0) {\n                        ballGrad.addColorStop(0, '#ffffff');\n                        ballGrad.addColorStop(0.4, '#ff9900');\n                        ballGrad.addColorStop(1, '#cc4400');\n                        ctx.shadowColor = '#ff6600';\n                        ctx.shadowBlur = 12;\n                    } else {\n                        ballGrad.addColorStop(0, '#ffffff');\n                        ballGrad.addColorStop(0.5, '#e8e8ff');\n                        ballGrad.addColorStop(1, '#8899cc');\n                        ctx.shadowColor = 'rgba(150,180,255,0.6)';\n                        ctx.shadowBlur = 6;\n                    }\n                    ctx.fillStyle = ballGrad;\n                    ctx.beginPath();\n                    ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);\n                    ctx.fill();\n                    ctx.shadowColor = 'transparent';\n                    ctx.shadowBlur = 0;\n                    ctx.fillStyle = 'rgba(255,255,255,0.7)';\n                    ctx.beginPath();\n                    ctx.arc(ball.x - ball.radius * 0.3, ball.y - ball.radius * 0.3, ball.radius * 0.3, 0, Math.PI * 2);\n                    ctx.fill();\n                }\n\n                // 球拍等待提示\n                if (ballWaiting && gameState === STATE.PLAYING) {\n                    const bx = paddleX, by = PADDLE_Y - PADDLE_H / 2 - BALL_RADIUS;\n                    const grad = ctx.createRadialGradient(bx - BALL_RADIUS * 0.25, by - BALL_RADIUS * 0.25, BALL_RADIUS * 0.1, bx, by, BALL_RADIUS);\n                    grad.addColorStop(0, '#ffffff'); grad.addColorStop(0.5, '#e8e8ff'); grad.addColorStop(1, '#8899cc');\n                    ctx.fillStyle = grad;\n                    ctx.beginPath();\n                    ctx.arc(bx, by, BALL_RADIUS, 0, Math.PI * 2);\n                    ctx.fill();\n                    ctx.fillStyle = 'rgba(255,255,255,0.7)';\n                    ctx.beginPath();\n                    ctx.arc(bx - BALL_RADIUS * 0.3, by - BALL_RADIUS * 0.3, BALL_RADIUS * 0.3, 0, Math.PI * 2);\n                    ctx.fill();\n                    ctx.fillStyle = 'rgba(255,255,255,0.7)';\n                    ctx.font = `${BALL_RADIUS*1.6}px sans-serif`;\n                    ctx.textAlign = 'center';\n                    ctx.fillText('↑', bx, by - BALL_RADIUS - 16);\n                }\n\n                // 球拍\n                const paddleGrad = ctx.createLinearGradient(paddleX - PADDLE_W / 2, PADDLE_Y, paddleX + PADDLE_W / 2, PADDLE_Y);\n                if (paddleWidthMultiplier > 1) {\n                    paddleGrad.addColorStop(0, '#5ea0ff');\n                    paddleGrad.addColorStop(0.5, '#8ec8ff');\n                    paddleGrad.addColorStop(1, '#5ea0ff');\n                    ctx.shadowColor = '#4da6ff';\n                    ctx.shadowBlur = 14;\n                } else {\n                    paddleGrad.addColorStop(0, '#d0d0e8');\n                    paddleGrad.addColorStop(0.5, '#f0f0ff');\n                    paddleGrad.addColorStop(1, '#b0b0d0');\n                    ctx.shadowColor = 'rgba(200,200,255,0.5)';\n                    ctx.shadowBlur = 6;\n                }\n                ctx.fillStyle = paddleGrad;\n                ctx.beginPath();\n                roundRect(ctx, paddleX - PADDLE_W / 2, PADDLE_Y - PADDLE_H / 2, PADDLE_W, PADDLE_H, PADDLE_H / 2);\n                ctx.fill();\n                ctx.shadowColor = 'transparent';\n                ctx.shadowBlur = 0;\n                ctx.fillStyle = 'rgba(255,255,255,0.4)';\n                ctx.beginPath();\n                roundRect(ctx, paddleX - PADDLE_W / 2 + 4, PADDLE_Y - PADDLE_H / 2 + 1, PADDLE_W - 8, PADDLE_H * 0.35, PADDLE_H / 3);\n                ctx.fill();\n\n                // 粒子\n                for (let p of particles) {\n                    const alpha = p.life / p.maxLife;\n                    ctx.fillStyle = hexToRgba(p.color, alpha);\n                    ctx.beginPath();\n                    ctx.arc(p.x, p.y, p.size * alpha, 0, Math.PI * 2);\n                    ctx.fill();\n                }\n\n                ctx.restore();\n\n                if (flashAlpha > 0) {\n                    ctx.fillStyle = `rgba(255,255,255,${flashAlpha})`;\n                    ctx.fillRect(0, 0, W, H);\n                }\n\n                drawHUD();\n                drawOverlayIfNeeded();\n            }\n\n            function drawHUD() {\n                const fontSize = Math.max(11, Math.floor(W * 0.03));\n                ctx.fillStyle = '#fff';\n                ctx.font = `bold ${fontSize}px \"PingFang SC\",\"Helvetica Neue\",sans-serif`;\n                ctx.textAlign = 'left';\n                ctx.textBaseline = 'top';\n                const badgeH = fontSize + 14;\n                const badgeY = 6;\n                let cx = 8;\n\n                function badge(text, color, icon) {\n                    const w = ctx.measureText(icon + ' ' + text).width + 18;\n                    ctx.fillStyle = 'rgba(15,15,40,0.8)';\n                    ctx.strokeStyle = color;\n                    ctx.lineWidth = 1.5;\n                    ctx.beginPath();\n                    roundRect(ctx, cx, badgeY, w, badgeH, badgeH / 2);\n                    ctx.fill();\n                    ctx.stroke();\n                    ctx.fillStyle = color;\n                    ctx.fillText(icon + ' ' + text, cx + 9, badgeY + (badgeH - fontSize) / 2);\n                    cx += w + 6;\n                }\n\n                badge('第' + (currentLevel === 3 ? '∞' : currentLevel) + '关', '#7ec8ff', '🏰');\n                badge('' + score, '#a0ffa0', '⭐');\n                badge('' + lives, '#ff6b6b', '❤️');\n                badge(balls.length + '/' + maxBalls, '#ffd700', '🔵');\n\n                if (paddleWidthTimer > 0 || slowMotionTimer > 0 || pierceTimer > 0) {\n                    const effY = badgeY + badgeH + 6;\n                    let ex = 8;\n                    ctx.font = `${fontSize*0.85}px \"PingFang SC\",\"Helvetica Neue\",sans-serif`;\n                    if (paddleWidthTimer > 0) {\n                        const t = '↔加长 ' + paddleWidthTimer.toFixed(1) + 's';\n                        const ew = ctx.measureText(t).width + 14;\n                        ctx.fillStyle = 'rgba(15,15,40,0.7)';\n                        ctx.strokeStyle = '#4da6ff';\n                        ctx.lineWidth = 1;\n                        ctx.beginPath();\n                        roundRect(ctx, ex, effY, ew, fontSize + 10, fontSize / 2 + 5);\n                        ctx.fill(); ctx.stroke();\n                        ctx.fillStyle = '#4da6ff';\n                        ctx.fillText(t, ex + 7, effY + 5);\n                        ex += ew + 4;\n                    }\n                    if (slowMotionTimer > 0) {\n                        const t = '⏱减速 ' + slowMotionTimer.toFixed(1) + 's';\n                        const ew = ctx.measureText(t).width + 14;\n                        ctx.fillStyle = 'rgba(15,15,40,0.7)';\n                        ctx.strokeStyle = '#ffe066';\n                        ctx.lineWidth = 1;\n                        ctx.beginPath();\n                        roundRect(ctx, ex, effY, ew, fontSize + 10, fontSize / 2 + 5);\n                        ctx.fill(); ctx.stroke();\n                        ctx.fillStyle = '#ffe066';\n                        ctx.fillText(t, ex + 7, effY + 5);\n                        ex += ew + 4;\n                    }\n                    if (pierceTimer > 0) {\n                        const t = '⚡穿透 ' + pierceTimer.toFixed(1) + 's';\n                        const ew = ctx.measureText(t).width + 14;\n                        ctx.fillStyle = 'rgba(15,15,40,0.7)';\n                        ctx.strokeStyle = '#ff9900';\n                        ctx.lineWidth = 1;\n                        ctx.beginPath();\n                        roundRect(ctx, ex, effY, ew, fontSize + 10, fontSize / 2 + 5);\n                        ctx.fill(); ctx.stroke();\n                        ctx.fillStyle = '#ff9900';\n                        ctx.fillText(t, ex + 7, effY + 5);\n                        ex += ew + 4;\n                    }\n                }\n            }\n\n            function drawOverlayIfNeeded() {\n                if (gameState === STATE.MENU) {\n                    drawOverlay('🎯 打砖块大冒险', '点击屏幕开始游戏', [\n                        '🏆 3个关卡 · 最后一关无尽模式',\n                        '🎁 道具：分裂球·加长球拍·减速·穿透·额外生命',\n                        '💣 特殊砖：金色⭐·炸弹💥 (钢砖已移除)',\n                        '🔮 球上限27个 · 无尽模式砖块会复活',\n                        '📱 滑动控制球拍 · 点击发射球',\n                    ]);\n                } else if (gameState === STATE.GAME_OVER) {\n                    drawOverlay('游戏结束 💔', `最终得分: ${score}`, [\n                        `到达关卡: ${currentLevel === 3 ? '无尽模式' : '第' + currentLevel + '关'}`,\n                        `最高同时球数: ${totalBallsEver}`,\n                        '点击屏幕重新开始',\n                    ]);\n                } else if (gameState === STATE.LEVEL_CLEAR && currentLevel < 3) {\n                    drawOverlay(`🎉 第${currentLevel}关通过！`, `得分: ${score}`, [\n                        `准备进入${currentLevel === 2 ? '无尽模式' : '第' + (currentLevel + 1) + '关'}`,\n                        '点击屏幕继续',\n                    ]);\n                }\n            }\n\n            function drawOverlay(title, subtitle, lines) {\n                ctx.fillStyle = 'rgba(0,0,0,0.75)';\n                ctx.fillRect(0, 0, W, H);\n                const panelW = W * 0.85, panelH = H * 0.55;\n                const panelX = (W - panelW) / 2, panelY = (H - panelH) / 2;\n                ctx.fillStyle = 'rgba(20,20,50,0.9)';\n                ctx.strokeStyle = 'rgba(255,255,255,0.3)';\n                ctx.lineWidth = 2;\n                ctx.beginPath();\n                roundRect(ctx, panelX, panelY, panelW, panelH, 20);\n                ctx.fill(); ctx.stroke();\n\n                const titleSize = Math.floor(W * 0.055);\n                ctx.fillStyle = '#fff';\n                ctx.font = `bold ${titleSize}px \"PingFang SC\",\"Helvetica Neue\",sans-serif`;\n                ctx.textAlign = 'center';\n                ctx.textBaseline = 'middle';\n                ctx.fillText(title, W / 2, panelY + titleSize + 16);\n\n                const subSize = Math.floor(W * 0.038);\n                ctx.fillStyle = '#ffd700';\n                ctx.font = `bold ${subSize}px \"PingFang SC\",\"Helvetica Neue\",sans-serif`;\n                ctx.fillText(subtitle, W / 2, panelY + titleSize + subSize + 28);\n\n                const lineSize = Math.floor(W * 0.028);\n                ctx.fillStyle = '#ccc';\n                ctx.font = `${lineSize}px \"PingFang SC\",\"Helvetica Neue\",sans-serif`;\n                let ly = panelY + titleSize + subSize + 55;\n                for (let line of lines) {\n                    ctx.fillText(line, W / 2, ly);\n                    ly += lineSize + 8;\n                }\n                const hintY = panelY + panelH - 30;\n                ctx.font = `bold ${Math.floor(W * 0.032)}px \"PingFang SC\",\"Helvetica Neue\",sans-serif`;\n                const pulse = 0.6 + 0.4 * Math.sin(performance.now() / 600);\n                ctx.fillStyle = `rgba(255,255,255,${pulse})`;\n                ctx.fillText('👆 点击屏幕', W / 2, hintY);\n            }\n\n            function roundRect(ctx, x, y, w, h, r) {\n                ctx.moveTo(x + r, y);\n                ctx.lineTo(x + w - r, y);\n                ctx.quadraticCurveTo(x + w, y, x + w, y + r);\n                ctx.lineTo(x + w, y + h - r);\n                ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);\n                ctx.lineTo(x + r, y + h);\n                ctx.quadraticCurveTo(x, y + h, x, y + h - r);\n                ctx.lineTo(x, y + r);\n                ctx.quadraticCurveTo(x, y, x + r, y);\n                ctx.closePath();\n            }\n\n            function darkenColor(hex, factor) {\n                const r = parseInt(hex.slice(1, 3), 16);\n                const g = parseInt(hex.slice(3, 5), 16);\n                const b = parseInt(hex.slice(5, 7), 16);\n                return `rgb(${Math.floor(r * (1 - factor))},${Math.floor(g * (1 - factor))},${Math.floor(b * (1 - factor))})`;\n            }\n\n            function lightenColor(hex, factor) {\n                const r = parseInt(hex.slice(1, 3), 16);\n                const g = parseInt(hex.slice(3, 5), 16);\n                const b = parseInt(hex.slice(5, 7), 16);\n                return `rgb(${Math.min(255, Math.floor(r + (255 - r) * factor))},${Math.min(255, Math.floor(g + (255 - g) * factor))},${Math.min(255, Math.floor(b + (255 - b) * factor))})`;\n            }\n\n            function hexToRgba(hex, alpha) {\n                const r = parseInt(hex.slice(1, 3), 16);\n                const g = parseInt(hex.slice(3, 5), 16);\n                const b = parseInt(hex.slice(5, 7), 16);\n                return `rgba(${r},${g},${b},${alpha})`;\n            }\n\n            // ============ 游戏流程 ============\n            function startGame() {\n                currentLevel = 1;\n                score = 0;\n                lives = 3;\n                balls = [];\n                powerUps = [];\n                particles = [];\n                paddleX = W / 2;\n                prevPaddleX = W / 2;\n                paddleVelocity = 0;\n                paddleWidthMultiplier = 1;\n                paddleWidthTimer = 0;\n                slowMotionTimer = 0;\n                pierceTimer = 0;\n                ballWaiting = true;\n                shakeTimer = 0;\n                shakeIntensity = 0;\n                comboCount = 0;\n                comboTimer = 0;\n                totalBallsEver = 0;\n                flashAlpha = 0;\n                levelTransitionTimer = 0;\n                updateGameDimensions();\n                generateLevel(currentLevel);\n                gameState = STATE.PLAYING;\n            }\n\n            function restartGame() { startGame(); }\n\n            function advanceLevel() {\n                if (currentLevel < 3) {\n                    currentLevel++;\n                    balls = [];\n                    powerUps = [];\n                    particles = [];\n                    paddleX = W / 2;\n                    prevPaddleX = W / 2;\n                    paddleVelocity = 0;\n                    paddleWidthMultiplier = 1;\n                    paddleWidthTimer = 0;\n                    slowMotionTimer = 0;\n                    pierceTimer = 0;\n                    ballWaiting = true;\n                    shakeTimer = 0;\n                    shakeIntensity = 0;\n                    comboCount = 0;\n                    comboTimer = 0;\n                    totalBallsEver = 0;\n                    flashAlpha = 0;\n                    levelTransitionTimer = 0;\n                    updateGameDimensions();\n                    generateLevel(currentLevel);\n                    gameState = STATE.PLAYING;\n                }\n            }\n\n            function init() {\n                updateGameDimensions();\n                paddleX = W / 2;\n                prevPaddleX = W / 2;\n                touchX = W / 2;\n                generateLevel(1);\n                gameState = STATE.MENU;\n                balls = [];\n                powerUps = [];\n                particles = [];\n                ballWaiting = true;\n                lastTime = performance.now();\n            }\n\n            init();\n            requestAnimationFrame(gameLoop);\n        })();\n    </script>\n</body>\n</html>";
const SNAKE_BATTLE_HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#0c1322\">\n<title>贪吃蛇大作战·单机版</title>\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nhtml,body{height:100%;overflow:hidden;background:#0c1322;\n  font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft Yahei',sans-serif;\n  touch-action:none;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}\ncanvas#game{position:fixed;inset:0;display:block}\n.hidden{display:none!important}\n#hud{position:fixed;inset:0;pointer-events:none;z-index:10}\n#stats{position:absolute;left:10px;top:calc(10px + env(safe-area-inset-top));display:flex;flex-direction:column;gap:6px}\n.pill{background:rgba(10,18,35,.6);border:1px solid rgba(120,150,220,.25);color:#cdd8ee;\n  font-size:13px;font-weight:600;padding:5px 12px;border-radius:20px;backdrop-filter:blur(4px);width:max-content}\n.pill b{color:#ffdd59}\n#minimap{position:absolute;right:10px;bottom:calc(14px + env(safe-area-inset-bottom));width:110px;height:110px;\n  border-radius:50%;background:rgba(8,14,28,.7);border:1px solid rgba(255,70,80,.5)}\n#toasts{position:absolute;top:calc(72px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);\n  display:flex;flex-direction:column;gap:6px;align-items:center}\n.toast{background:rgba(200,40,60,.88);color:#fff;padding:6px 16px;border-radius:20px;font-size:13px;\n  font-weight:600;white-space:nowrap;animation:tIn .25s ease,tOut .4s ease 1.6s forwards}\n@keyframes tIn{from{transform:translateY(-16px);opacity:0}}\n@keyframes tOut{to{transform:translateY(-10px);opacity:0}}\n#joyBase{position:fixed;width:110px;height:110px;border-radius:50%;\n  border:2px solid rgba(140,170,255,.35);background:rgba(20,30,60,.25);\n  z-index:9;left:16px;bottom:24px;display:none}\n#joyKnob{position:absolute;left:50%;top:50%;width:48px;height:48px;border-radius:50%;\n  background:rgba(140,170,255,.55);border:2px solid rgba(200,220,255,.7);\n  transform:translate(-50%,-50%);transition:transform .05s linear}\n#boost{position:fixed;right:20px;bottom:36px;width:82px;height:82px;border-radius:50%;\n  background:rgba(20,30,60,.5);border:2px solid rgba(120,150,220,.35);\n  display:none;align-items:center;justify-content:center;font-size:13px;font-weight:700;\n  color:#8fb3ff;z-index:9;letter-spacing:2px;user-select:none;touch-action:none}\n#boost.active{background:rgba(74,144,217,.6);color:#fff;box-shadow:0 0 16px rgba(74,144,217,.7)}\n#startScreen{position:fixed;inset:0;z-index:20;display:flex;flex-direction:column;align-items:center;\n  justify-content:center;gap:13px;padding:20px;\n  background:radial-gradient(ellipse at 50% 30%,rgba(27,42,77,.92) 0%,rgba(12,19,34,.97) 70%)}\n#startScreen h1{color:#ffdd59;font-size:32px;font-weight:900;letter-spacing:3px;\n  text-shadow:0 2px 0 #b8860b,0 4px 12px rgba(0,0,0,.6)}\n#startBtn{margin-top:8px;padding:13px 54px;font-size:19px;font-weight:900;color:#fff;letter-spacing:3px;\n  border:none;border-radius:34px;cursor:pointer;\n  background:linear-gradient(180deg,#7ed957,#4caf50 60%,#3d8b40);\n  box-shadow:0 5px 0 #2d6b30,0 8px 18px rgba(0,0,0,.45);font-family:inherit}\n#startBtn:active{transform:translateY(3px);box-shadow:0 2px 0 #2d6b30}\n.best{color:#8fb3ff;font-size:13px}\n.tips{color:rgba(200,215,240,.55);font-size:12px;text-align:center;line-height:1.8}\n.tips b{color:#ffdd59}\n#deathScreen{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;background:rgba(5,10,20,.7)}\n#deathScreen .panel{width:min(84vw,320px);display:flex;flex-direction:column;gap:12px;align-items:center;\n  background:linear-gradient(180deg,#16233f,#0e1830);border:2px solid rgba(120,150,220,.3);border-radius:18px;padding:24px 22px}\n.deadTitle{color:#ff6b6b;font-size:26px;font-weight:900}\n#deathStats{width:100%;display:flex;flex-direction:column;gap:6px}\n#deathStats .row{display:flex;justify-content:space-between;color:#cdd8ee;font-size:14px}\n#deathStats .row b{color:#ffdd59}\n#retryBtn{width:100%;padding:12px;font-size:16px;font-weight:900;color:#fff;letter-spacing:2px;border:none;\n  border-radius:26px;background:linear-gradient(180deg,#7ed957,#4caf50 60%,#3d8b40);box-shadow:0 4px 0 #2d6b30;\n  font-family:inherit}\n#retryBtn:active{transform:translateY(2px);box-shadow:0 2px 0 #2d6b30}\n</style>\n</head>\n<body>\n<canvas id=\"game\"></canvas>\n<div id=\"joyBase\"><div id=\"joyKnob\"></div></div>\n<div id=\"boost\">加速</div>\n<div id=\"hud\" class=\"hidden\">\n  <div id=\"stats\">\n    <div class=\"pill\">长度 <b id=\"statLen\">10</b></div>\n    <div class=\"pill\">排名 <b id=\"statRank\">#-</b></div>\n    <div class=\"pill\">击杀 <b id=\"statKill\">0</b></div>\n  </div>\n  <canvas id=\"minimap\" width=\"220\" height=\"220\"></canvas>\n  <div id=\"toasts\"></div>\n</div>\n<div id=\"startScreen\">\n  <h1>贪吃蛇大作战</h1>\n  <div class=\"best\" id=\"bestText\"></div>\n  <button id=\"startBtn\">开 始 游 戏</button>\n  <div class=\"tips\">\n    左下摇杆控制方向 · 右下按钮加速<br>\n    加速消耗长度掉食物 · 撞墙会沿墙滑<br>\n    自己撞自己不会死 · 撞别的蛇头会死<br>\n    长度无上限 · 蛇口自动吸附附近食物<br>\n    <b>护盾</b>抵挡一次致命撞击\n  </div>\n</div>\n<div id=\"deathScreen\" class=\"hidden\">\n  <div class=\"panel\">\n    <div class=\"deadTitle\">你挂了！</div>\n    <div id=\"deathStats\">\n      <div class=\"row\"><span>本局长度</span><b id=\"dLen\">0</b></div>\n      <div class=\"row\"><span>击杀数量</span><b id=\"dKill\">0</b></div>\n      <div class=\"row\"><span>最高排名</span><b id=\"dRank\">#-</b></div>\n      <div class=\"row\"><span>历史最佳</span><b id=\"dBest\">0</b></div>\n    </div>\n    <button id=\"retryBtn\">再来一局</button>\n  </div>\n</div>\n<script>\n'use strict';\nconst TAU = Math.PI * 2;\nconst MAP_R = 3400;\nconst AI_COUNT = 16;\nconst FOOD_MAX = 1500;\nconst BASE_SPEED = 130;\nconst BOOST_SPEED = 230;\nconst GRID = 160;\nconst MAX_RADIUS = 14;\nconst BASE_RADIUS = 6.5;\nconst GROW_PER_FOOD = 0.05;\nconst SPAWN_INVULN = 2.2;\nconst SHIELD_INVULN = 1.3;\nconst EAT_PULL_BASE = 190;\nconst EAT_PULL_PER_R = 3.5;\nconst FOOD_EDGE_MARGIN = 30;\n\nconst rand = (a,b) => a + Math.random() * (b-a);\nconst clamp = (v,a,b) => v<a?a:v>b?b:v;\nconst dist2 = (x1,y1,x2,y2) => { const dx=x2-x1, dy=y2-y1; return dx*dx+dy*dy; };\nconst angNorm = a => { while(a>Math.PI) a-=TAU; while(a<-Math.PI) a+=TAU; return a; };\n\nconst $ = id => document.getElementById(id);\nconst cv = $('game'), ctx = cv.getContext('2d');\nconst mm = $('minimap'), mctx = mm.getContext('2d');\nconst hud = $('hud'), startScreen = $('startScreen'), deathScreen = $('deathScreen');\nconst statLen = $('statLen'), statRank = $('statRank'), statKill = $('statKill');\nconst toastsEl = $('toasts'), bestText = $('bestText');\nconst joyBase = $('joyBase'), joyKnob = $('joyKnob'), boostBtn = $('boost');\n\nlet W = 0, H = 0, DPR = 1;\nfunction resize(){\n  DPR = Math.min(window.devicePixelRatio || 1, 2);\n  W = innerWidth; H = innerHeight;\n  cv.width = W * DPR; cv.height = H * DPR;\n  cv.style.width = W + 'px'; cv.style.height = H + 'px';\n}\naddEventListener('resize', resize); resize();\n\n/* 食物空间网格 */\nconst foodGrid = new Map();\nlet foodCount = 0;\nconst cellKey = (cx,cy) => cx * 100003 + cy;\nfunction addFood(f){\n  f._cx = Math.floor(f.x / GRID);\n  f._cy = Math.floor(f.y / GRID);\n  const k = cellKey(f._cx, f._cy);\n  let arr = foodGrid.get(k);\n  if(!arr){ arr = []; foodGrid.set(k, arr); }\n  f._i = arr.length; f._arr = arr; arr.push(f);\n}\nfunction removeFood(f){\n  const arr = f._arr, last = arr.pop();\n  if(last !== f){ arr[f._i] = last; last._i = f._i; }\n}\nfunction foodMove(f){\n  const cx = Math.floor(f.x / GRID), cy = Math.floor(f.y / GRID);\n  if(cx === f._cx && cy === f._cy) return;\n  removeFood(f);\n  f._cx = cx; f._cy = cy;\n  const k = cellKey(cx, cy);\n  let arr = foodGrid.get(k);\n  if(!arr){ arr = []; foodGrid.set(k, arr); }\n  f._i = arr.length; f._arr = arr; arr.push(f);\n}\nfunction clampToMap(x, y, margin){\n  const m = margin == null ? FOOD_EDGE_MARGIN : margin;\n  const dr = Math.hypot(x, y);\n  const maxR = MAP_R - m;\n  if(dr > maxR && dr > 0.0001){\n    const k = maxR / dr;\n    return [x * k, y * k];\n  }\n  return [x, y];\n}\nfunction spawnFood(x, y, value, color, big){\n  if(foodCount > FOOD_MAX + 1000) return;\n  const p = clampToMap(x, y);\n  const f = {\n    x: p[0], y: p[1], value,\n    r: 2.4 + Math.min(value, 8) * 0.85,\n    color, big: !!big,\n    phase: Math.random() * TAU\n  };\n  addFood(f); foodCount++;\n}\nfunction eatFood(f){ removeFood(f); foodCount--; }\nfunction queryFoods(x, y, r, out){\n  out.length = 0;\n  const c0x = Math.floor((x-r)/GRID), c1x = Math.floor((x+r)/GRID);\n  const c0y = Math.floor((y-r)/GRID), c1y = Math.floor((y+r)/GRID);\n  for(let cy=c0y; cy<=c1y; cy++)\n    for(let cx=c0x; cx<=c1x; cx++){\n      const arr = foodGrid.get(cellKey(cx, cy));\n      if(arr) for(let i=0;i<arr.length;i++) out.push(arr[i]);\n    }\n  return out;\n}\nconst randFoodColor = () => 'hsl(' + ((Math.random()*360)|0) + ',85%,62%)';\nfunction initFoods(n){\n  for(let i=0;i<n;i++){\n    const a = rand(0, TAU), r = Math.sqrt(Math.random()) * (MAP_R - 100);\n    spawnFood(Math.cos(a)*r, Math.sin(a)*r, 1 + ((Math.random()*3)|0), randFoodColor(), false);\n  }\n}\n\nconst PALETTE = ['#E74C3C','#E67E22','#F1C40F','#2ECC71','#1ABC9C','#3498DB','#9B59B6','#E91E63','#FF5722','#00BCD4'];\nconst randomColor = () => PALETTE[(Math.random()*PALETTE.length)|0];\nlet items = [];\nlet itemTimer = 0;\n\n/* 蛇 */\nlet snakeSeq = 0;\nclass Snake {\n  constructor(o){\n    this.id = ++snakeSeq;\n    this.isPlayer = !!o.isPlayer;\n    this.color = o.color || (this.isPlayer ? '#4A90D9' : randomColor());\n    this.name = o.name || '';\n    this.x = o.x; this.y = o.y;\n    this.angle = o.angle != null ? o.angle : Math.random() * TAU;\n    this.targetAngle = null;\n    this.length = o.length || 10;\n    this.radius = BASE_RADIUS;\n    this.headR = BASE_RADIUS * 1.3;\n    this.dead = false;\n    this.kills = 0;\n    this.bestRank = 99;\n    this.invincible = SPAWN_INVULN;\n    this.boost = false;\n    this.boostTimer = 0;\n    this.dropTimer = 0;\n    this.decideTimer = Math.random() * 0.2;\n    this.wander = this.angle;\n    this.shield = false;\n    this.aiRatio = o.aiRatio || 0;\n    this.growRate = o.growRate || 1.2;\n    this.path = [];\n    this.body = [];\n    this.bbox = { minX:0, minY:0, maxX:0, maxY:0 };\n\n    const n = this.bodyCount() + 2;\n    const sp = this.spacingNow();\n    for(let i=n; i>=0; i--){\n      this.path.push({\n        x: this.x - Math.cos(this.angle) * sp * i,\n        y: this.y - Math.sin(this.angle) * sp * i\n      });\n    }\n    this.recompute();\n  }\n  targetRadius(){ return clamp(BASE_RADIUS + Math.sqrt(this.length) * 0.26, BASE_RADIUS, MAX_RADIUS); }\n  bodyCount(){ return 6 + Math.floor(this.length * 0.9); }\n  spacingNow(){ return Math.max(3.5, this.radius * 0.5); }\n\n  recompute(){\n    const sp = this.spacingNow(), need = this.bodyCount();\n    const path = this.path, body = this.body;\n    let bi = 0;\n    const set = (x, y) => {\n      let p = body[bi];\n      if(!p){ p = { x:0, y:0 }; body[bi] = p; }\n      p.x = x; p.y = y; bi++;\n    };\n    if(path.length) set(path[0].x, path[0].y);\n    else set(this.x, this.y);\n\n    let minX=this.x, maxX=this.x, minY=this.y, maxY=this.y;\n    let distNeed = sp;\n    let segX = path[0].x, segY = path[0].y;\n\n    for(let i=1;i<path.length && bi<need;i++){\n      const p = path[i];\n      let dx = p.x - segX, dy = p.y - segY;\n      let seg = Math.hypot(dx, dy);\n      while(seg >= distNeed && bi < need){\n        const t = distNeed / seg;\n        const nx = segX + dx * t, ny = segY + dy * t;\n        set(nx, ny);\n        if(nx<minX)minX=nx; if(nx>maxX)maxX=nx;\n        if(ny<minY)minY=ny; if(ny>maxY)maxY=ny;\n        segX = nx; segY = ny;\n        dx = p.x - nx; dy = p.y - ny;\n        seg = Math.hypot(dx, dy);\n        distNeed = sp;\n      }\n      distNeed -= seg;\n      segX = p.x; segY = p.y;\n    }\n    const last = body[bi-1];\n    while(bi < need){ set(last.x, last.y); bi++; }\n    body.length = need;\n\n    this.bbox.minX = minX - this.radius;\n    this.bbox.maxX = maxX + this.radius;\n    this.bbox.minY = minY - this.radius;\n    this.bbox.maxY = maxY + this.radius;\n  }\n\n  trimPath(){\n    const total = this.bodyCount() * this.spacingNow() + this.spacingNow() * 3;\n    let acc = 0;\n    const path = this.path;\n    for(let i=1;i<path.length;i++){\n      acc += Math.hypot(path[i].x - path[i-1].x, path[i].y - path[i-1].y);\n      if(acc > total){ path.length = i + 1; return; }\n    }\n  }\n\n  update(dt){\n    if(this.invincible > 0) this.invincible -= dt;\n\n    if(this.targetAngle != null){\n      const diff = angNorm(this.targetAngle - this.angle);\n      const maxTurn = Math.max(2.5, 5.0 - this.radius * 0.1) * dt;\n      this.angle += clamp(diff, -maxTurn, maxTurn);\n    }\n\n    let boosting = false;\n    if(this.isPlayer){\n      boosting = input.boost && this.length > 20;\n    }else{\n      if(this.boostTimer > 0) this.boostTimer -= dt;\n      boosting = this.boostTimer > 0 && this.length > 25;\n    }\n    this.boost = boosting;\n\n    const sp = boosting ? BOOST_SPEED : BASE_SPEED;\n    let nx = this.x + Math.cos(this.angle) * sp * dt;\n    let ny = this.y + Math.sin(this.angle) * sp * dt;\n\n    // ★ 用 headR 做边界限制，视觉上不会越界\n    const dr = Math.hypot(nx, ny);\n    const maxR = MAP_R - this.headR;\n    if(dr > maxR){\n      const k = maxR / dr;\n      nx *= k; ny *= k;\n    }\n    this.x = nx; this.y = ny;\n\n    if(boosting){\n      this.length = Math.max(10, this.length - 12 * dt);\n      this.dropTimer -= dt;\n      if(this.dropTimer <= 0){\n        this.dropTimer = 0.16;\n        const tail = this.body[this.body.length - 1] || this;\n        spawnFood(\n          tail.x + rand(-4,4),\n          tail.y + rand(-4,4),\n          1, this.color, false\n        );\n      }\n    }\n\n    const tr = this.targetRadius();\n    this.radius += (tr - this.radius) * Math.min(1, dt * 3);\n    this.headR = this.radius * 1.3;\n\n    const h = this.path[0];\n    if(!h) this.path.unshift({ x:this.x, y:this.y });\n    else if(dist2(h.x, h.y, this.x, this.y) < 0.36){ h.x = this.x; h.y = this.y; }\n    else this.path.unshift({ x:this.x, y:this.y });\n\n    this.trimPath();\n    this.recompute();\n  }\n}\n\n/* AI */\nconst _qa = [];\nfunction aiThink(s, dt){\n  s.decideTimer -= dt;\n  if(s.decideTimer > 0) return;\n  s.decideTimer = 0.12 + Math.random() * 0.1;\n\n  const look = 90 + s.radius * 7;\n  const test = ang => {\n    const x = s.x + Math.cos(ang) * look;\n    const y = s.y + Math.sin(ang) * look;\n    if(Math.hypot(x, y) > MAP_R - 100) return false;\n    const safe = s.radius * 2.2;\n    for(const o of snakes){\n      if(o === s || o.dead) continue;\n      const bb = o.bbox;\n      if(x < bb.minX - safe || x > bb.maxX + safe ||\n         y < bb.minY - safe || y > bb.maxY + safe) continue;\n      const rr = safe + o.radius, rr2 = rr * rr;\n      const b = o.body;\n      for(let i=0; i<b.length; i++)\n        if(dist2(x, y, b[i].x, b[i].y) < rr2) return false;\n    }\n    return true;\n  };\n\n  if(!test(s.angle)){\n    const offs = [0.55, -0.55, 1.1, -1.1, 1.8, -1.8, 2.6, -2.6];\n    let found = null;\n    for(const off of offs) if(test(s.angle + off)){ found = s.angle + off; break; }\n    s.targetAngle = found != null ? found : Math.atan2(-s.y, -s.x);\n    return;\n  }\n\n  const foods = queryFoods(s.x, s.y, 420, _qa);\n  let best = null, bs = 0;\n  for(let i=0; i<foods.length; i++){\n    const f = foods[i];\n    const d = Math.hypot(f.x - s.x, f.y - s.y) + 1;\n    const v = f.value / d;\n    if(v > bs){ bs = v; best = f; }\n  }\n  if(best) s.targetAngle = Math.atan2(best.y - s.y, best.x - s.x);\n  else{\n    s.wander += rand(-0.6, 0.6);\n    if(Math.hypot(s.x + Math.cos(s.wander) * 600, s.y + Math.sin(s.wander) * 600) > MAP_R - 200)\n      s.targetAngle = Math.atan2(-s.y, -s.x);\n    else s.targetAngle = s.wander;\n  }\n  if(s.length > 60 && Math.random() < 0.015) s.boostTimer = rand(0.4, 1);\n}\n\n/* 世界状态 */\nlet gameState = 'menu';\nlet player = null;\nlet snakes = [];\nlet respawnQueue = [];\nlet cam = { x:0, y:0 };\nlet zoom = 0.7;\nlet tNow = 0, hudTimer = 0, foodSpawnTimer = 0;\nlet bestLen = 0;\ntry { bestLen = +localStorage.getItem('snake_best_v11') || 0; } catch(e){}\n\nfunction assignAIRatio(){\n  const r = Math.random();\n  if(r < 0.15) return 0.20 + Math.random() * 0.15;\n  if(r < 0.50) return 0.08 + Math.random() * 0.10;\n  return 0.02 + Math.random() * 0.06;\n}\n\nfunction safeSpawn(){\n  for(let t=0; t<30; t++){\n    const a = rand(0, TAU), r = Math.sqrt(Math.random()) * (MAP_R - 500);\n    const x = Math.cos(a) * r, y = Math.sin(a) * r;\n    let ok = true;\n    for(const s of snakes)\n      if(!s.dead && dist2(x, y, s.x, s.y) < 350*350){ ok = false; break; }\n    if(ok) return [x, y];\n  }\n  const a = rand(0, TAU), r = Math.sqrt(Math.random()) * (MAP_R - 800);\n  return [Math.cos(a) * r, Math.sin(a) * r];\n}\n\nfunction spawnAI(initialLength){\n  let pos = safeSpawn();\n  let x = pos[0], y = pos[1];\n  const dr = Math.hypot(x, y);\n  const maxR = MAP_R - 300;\n  if(dr > maxR){\n    const k = maxR / dr;\n    x *= k; y *= k;\n  }\n\n  const ratio = assignAIRatio();\n  const p = Math.max(10, player ? player.length : 10);\n  let len = initialLength;\n  if(len == null){\n    len = Math.max(12, Math.floor(p * ratio * rand(0.5, 1.0)));\n  }\n  const s = new Snake({\n    isPlayer: false, x, y, length: len, aiRatio: ratio,\n    growRate: 1.5 + ratio * 25\n  });\n  snakes.push(s);\n}\n\nfunction setupMenuWorld(){\n  snakes.length = 0; respawnQueue.length = 0;\n  foodGrid.clear(); foodCount = 0;\n  items.length = 0; itemTimer = 0;\n  for(let i=0; i<AI_COUNT; i++) spawnAI(rand(30, 200));\n  initFoods(800);\n  cam.x = 0; cam.y = 0; zoom = 0.7;\n  gameState = 'menu';\n  startScreen.classList.remove('hidden');\n  deathScreen.classList.add('hidden');\n  hud.classList.add('hidden');\n  joyBase.style.display = 'none';\n  boostBtn.style.display = 'none';\n  bestText.textContent = bestLen > 0 ? '历史最佳长度：' + bestLen : '';\n}\n\nfunction startGame(){\n  snakes.length = 0; respawnQueue.length = 0;\n  foodGrid.clear(); foodCount = 0;\n  items.length = 0; itemTimer = 0;\n\n  const [px, py] = safeSpawn();\n  player = new Snake({\n    isPlayer: true, x: px, y: py,\n    length: 12, color: '#4A90D9'\n  });\n  snakes.push(player);\n\n  for(let i=0; i<AI_COUNT; i++) spawnAI(rand(20, 160));\n  initFoods(800);\n\n  cam.x = px; cam.y = py; zoom = 1.15;\n  gameState = 'play';\n  startScreen.classList.add('hidden');\n  deathScreen.classList.add('hidden');\n  hud.classList.remove('hidden');\n  joyBase.style.display = 'block';\n  boostBtn.style.display = 'flex';\n  hudTimer = 0;\n  updateHUD();\n}\n\n/* 击杀 */\nfunction kill(s, killer){\n  if(s.dead) return;\n  s.dead = true;\n  if(killer && !killer.dead) killer.kills++;\n  if(killer === player){ toast('你击败了对手！'); sfx.kill(); }\n\n  const b = s.body;\n  const step = Math.max(1, Math.ceil(b.length / 45));\n  const per = clamp(s.length / Math.max(1, (b.length/step)|0), 1, 10);\n  for(let k=0; k<b.length; k+=step){\n    spawnFood(\n      b[k].x + rand(-s.radius, s.radius) * 0.6,\n      b[k].y + rand(-s.radius, s.radius) * 0.6,\n      per, s.color, true\n    );\n  }\n\n  if(s === player){\n    sfx.die();\n    gameState = 'dead';\n    setTimeout(showDeath, 900);\n  }else{\n    respawnQueue.push(tNow + rand(2, 4));\n  }\n}\n\nfunction showDeath(){\n  if(gameState !== 'dead') return;\n  const len = Math.round(player.length);\n  if(len > bestLen){\n    bestLen = len;\n    try { localStorage.setItem('snake_best_v11', bestLen); } catch(e){}\n  }\n  $('dLen').textContent = len;\n  $('dKill').textContent = player.kills;\n  $('dRank').textContent = '#' + player.bestRank;\n  $('dBest').textContent = bestLen;\n  deathScreen.classList.remove('hidden');\n}\n\nfunction toast(txt){\n  const d = document.createElement('div');\n  d.className = 'toast';\n  d.textContent = txt;\n  toastsEl.append(d);\n  setTimeout(() => d.remove(), 2100);\n}\n\n/* 音效 */\nlet audioCtx = null, muted = false;\nfunction initAudio(){\n  if(!audioCtx){ try { audioCtx = new (window.AudioContext||window.webkitAudioContext)(); } catch(e){} }\n  if(audioCtx && audioCtx.state === 'suspended') audioCtx.resume();\n}\nfunction beep(f1, f2, dur, type, vol){\n  if(muted || !audioCtx) return;\n  const t = audioCtx.currentTime;\n  const o = audioCtx.createOscillator(), g = audioCtx.createGain();\n  o.type = type;\n  o.frequency.setValueAtTime(f1, t);\n  o.frequency.exponentialRampToValueAtTime(Math.max(30, f2), t + dur);\n  g.gain.setValueAtTime(vol, t);\n  g.gain.exponentialRampToValueAtTime(0.001, t + dur);\n  o.connect(g); g.connect(audioCtx.destination);\n  o.start(t); o.stop(t + dur + 0.02);\n}\nconst sfx = {\n  eat: () => beep(rand(500,900), rand(700,1100), 0.06, 'triangle', 0.05),\n  kill: () => { beep(500,900,0.12,'square',0.07); setTimeout(()=>beep(700,1300,0.15,'square',0.07),90); },\n  die: () => beep(280,60,0.5,'sawtooth',0.12),\n  item: () => beep(700,1400,0.15,'sine',0.08)\n};\n\n/* 碰撞 */\nfunction collisions(){\n  for(const s of snakes){\n    if(s.dead) continue;\n    if(Math.hypot(s.x, s.y) > MAP_R - s.headR * 0.5) kill(s, null);\n  }\n  for(let i=0; i<snakes.length; i++){\n    const a = snakes[i];\n    if(a.dead || a.invincible > 0) continue;\n    for(let j=0; j<snakes.length; j++){\n      if(i === j) continue;\n      const b = snakes[j];\n      if(b.dead || b.invincible > 0) continue;\n\n      const bb = b.bbox, m = a.radius;\n      if(a.x < bb.minX - m || a.x > bb.maxX + m ||\n         a.y < bb.minY - m || a.y > bb.maxY + m) continue;\n\n      const rr = a.radius * 0.55 + b.radius;\n      const rr2 = rr * rr;\n      const body = b.body;\n      let hit = false;\n      const bodyStep = body.length > 200 ? 2 : 1;\n      for(let k=0; k<body.length; k+=bodyStep){\n        if(dist2(a.x, a.y, body[k].x, body[k].y) < rr2){ hit = true; break; }\n      }\n      if(hit){\n        if(a.isPlayer && a.shield){\n          a.shield = false;\n          a.invincible = SHIELD_INVULN;\n          const pa = Math.atan2(a.y - b.y, a.x - b.x);\n          a.x += Math.cos(pa) * 28;\n          a.y += Math.sin(pa) * 28;\n          const dr = Math.hypot(a.x, a.y);\n          const mr = MAP_R - a.headR;\n          if(dr > mr){ const kk = mr/dr; a.x *= kk; a.y *= kk; }\n        }else{\n          kill(a, b);\n        }\n        break;\n      }\n    }\n  }\n}\n\n/* 主更新 */\nconst _qb = [];\nfunction update(dt){\n  tNow += dt;\n\n  for(const s of snakes){\n    if(s.dead) continue;\n    if(!s.isPlayer) aiThink(s, dt);\n    s.update(dt);\n  }\n\n  if(player && !player.dead){\n    const p = player.length;\n    for(const s of snakes){\n      if(s.dead || s.isPlayer) continue;\n      if(s.aiRatio <= 0) continue;\n      const target = Math.max(12, Math.floor(p * s.aiRatio));\n      if(s.length < target){\n        s.length = Math.min(target, s.length + dt * s.growRate);\n      }\n    }\n  }\n\n  for(const s of snakes){\n    if(s.dead) continue;\n    const foods = queryFoods(s.x, s.y, 90 + s.radius * 2.5, _qb);\n    let pullR;\n    if(s.isPlayer){\n      pullR = EAT_PULL_BASE + s.radius * EAT_PULL_PER_R;\n    }else{\n      pullR = 110 + s.radius * 2.2;\n    }\n    for(let i=0; i<foods.length; i++){\n      const f = foods[i];\n      const dx = s.x - f.x, dy = s.y - f.y;\n      const d = Math.hypot(dx, dy) || 0.001;\n      if(d < s.radius + f.r + 2){\n        s.length += f.value;\n        s.radius = Math.min(MAX_RADIUS, s.radius + GROW_PER_FOOD);\n        eatFood(f);\n        if(s.isPlayer) sfx.eat();\n      }else if(d < pullR){\n        const pull = (520 + (pullR - d) * 4) * dt;\n        const mv = Math.min(pull, d - 1) / d;\n        f.x += dx * mv; f.y += dy * mv;\n        // ★ 磁吸移动后也要强制 clamp 在地图内\n        const p = clampToMap(f.x, f.y);\n        f.x = p[0]; f.y = p[1];\n        foodMove(f);\n      }\n    }\n  }\n\n  if(player && !player.dead){\n    for(let i=items.length-1; i>=0; i--){\n      const it = items[i];\n      if(Math.hypot(player.x - it.x, player.y - it.y) < player.headR + it.r + 4){\n        player.shield = true;\n        items.splice(i, 1);\n        sfx.item();\n      }\n    }\n  }\n\n  collisions();\n\n  while(respawnQueue.length && respawnQueue[0] < tNow){\n    respawnQueue.shift();\n    spawnAI();\n  }\n\n  itemTimer -= dt;\n  if(itemTimer <= 0 && items.length < 2 && player){\n    itemTimer = 6;\n    spawnItem();\n  }\n\n  foodSpawnTimer -= dt;\n  if(foodSpawnTimer <= 0){\n    foodSpawnTimer = 0.25;\n    for(let i=0; i<4; i++){\n      if(foodCount < FOOD_MAX){\n        const a = rand(0, TAU);\n        const r = Math.sqrt(Math.random()) * (MAP_R - 100);\n        spawnFood(Math.cos(a)*r, Math.sin(a)*r, 1 + ((Math.random()*3)|0), randFoodColor(), false);\n      }\n    }\n  }\n\n  for(let i=snakes.length-1; i>=0; i--) if(snakes[i].dead) snakes.splice(i, 1);\n\n  // ★ 镜头缩放跟随长度动态拉远\n  if(player && !player.dead && gameState === 'play'){\n    cam.x += (player.x - cam.x) * Math.min(1, dt * 6);\n    cam.y += (player.y - cam.y) * Math.min(1, dt * 6);\n    // 长度越长，镜头越远（下限 0.5）\n    const zt = clamp(1.4 - Math.min(player.length / 1000, 1) * 0.8, 0.5, 1.2);\n    zoom += (zt - zoom) * Math.min(1, dt * 2);\n  }else if(gameState === 'menu'){\n    let big = null;\n    for(const s of snakes) if(!s.dead && (!big || s.length > big.length)) big = s;\n    if(big){\n      cam.x += (big.x - cam.x) * Math.min(1, dt * 0.8);\n      cam.y += (big.y - cam.y) * Math.min(1, dt * 0.8);\n    }\n  }\n\n  if(gameState === 'play' && player && !player.dead){\n    hudTimer -= dt;\n    if(hudTimer <= 0){ hudTimer = 0.3; updateHUD(); }\n  }\n}\n\nfunction spawnItem(){\n  if(!player) return;\n  for(let t=0; t<30; t++){\n    const a = rand(0, TAU), r = Math.sqrt(Math.random()) * (MAP_R - 400);\n    const x = Math.cos(a) * r, y = Math.sin(a) * r;\n    if(Math.hypot(x - player.x, y - player.y) < 300) continue;\n    items.push({ x, y, type: 'shield', r: 14, phase: Math.random() * TAU });\n    return;\n  }\n}\n\n/* 渲染 */\nfunction hexPath(cx, cy, s){\n  for(let k=0; k<6; k++){\n    const a = Math.PI/3*k + Math.PI/6;\n    const x = cx + Math.cos(a)*s, y = cy + Math.sin(a)*s;\n    if(k === 0) ctx.moveTo(x, y);\n    else ctx.lineTo(x, y);\n  }\n  ctx.closePath();\n}\nfunction drawGrid(x0, y0, x1, y1){\n  const s = 46, w = Math.sqrt(3)*s, h = 1.5*s;\n  const r0 = Math.floor((y0-s)/h)-1, r1 = Math.ceil((y1+s)/h)+1;\n  ctx.strokeStyle = 'rgba(120,150,220,.07)';\n  ctx.lineWidth = 1.2;\n  ctx.beginPath();\n  for(let row=r0; row<=r1; row++){\n    const cy = row*h, off = (row & 1) ? w/2 : 0;\n    const c0 = Math.floor((x0-off-s)/w)-1, c1 = Math.ceil((x1-off+s)/w)+1;\n    for(let col=c0; col<=c1; col++) hexPath(col*w + off, cy, s);\n  }\n  ctx.stroke();\n}\nfunction drawBoundary(x0, y0, x1, y1){\n  ctx.beginPath();\n  ctx.rect(x0, y0, x1-x0, y1-y0);\n  ctx.arc(0, 0, MAP_R, 0, TAU, true);\n  ctx.fillStyle = 'rgba(150,20,30,.45)';\n  ctx.fill('evenodd');\n\n  ctx.beginPath();\n  ctx.arc(0, 0, MAP_R, 0, TAU);\n  ctx.strokeStyle = 'rgba(255,70,80,.25)';\n  ctx.lineWidth = 16;\n  ctx.stroke();\n  ctx.strokeStyle = 'rgba(255,70,80,.95)';\n  ctx.lineWidth = 5;\n  ctx.stroke();\n}\nfunction drawFoods(x0, y0, x1, y1){\n  const p = 24;\n  const c0x = Math.floor((x0-p)/GRID), c1x = Math.floor((x1+p)/GRID);\n  const c0y = Math.floor((y0-p)/GRID), c1y = Math.floor((y1+p)/GRID);\n  for(let cy=c0y; cy<=c1y; cy++)\n    for(let cx=c0x; cx<=c1x; cx++){\n      const arr = foodGrid.get(cellKey(cx, cy));\n      if(!arr) continue;\n      for(let i=0; i<arr.length; i++){\n        const f = arr[i];\n        // ★ 终极防御：如果食物意外跑到边界外，跳过渲染\n        if(Math.hypot(f.x, f.y) > MAP_R - 5) continue;\n        const r = f.r * (1 + 0.18 * Math.sin(tNow*2.5 + f.phase));\n        ctx.fillStyle = f.color;\n        ctx.globalAlpha = 0.22;\n        ctx.beginPath();\n        ctx.arc(f.x, f.y, r * (f.big ? 2.6 : 2.1), 0, TAU);\n        ctx.fill();\n        ctx.globalAlpha = 1;\n        ctx.beginPath();\n        ctx.arc(f.x, f.y, r, 0, TAU);\n        ctx.fill();\n      }\n    }\n}\nfunction drawItems(){\n  for(const it of items){\n    const pulse = 1 + Math.sin(tNow*4 + it.phase) * 0.12;\n    const r = it.r * pulse;\n    ctx.beginPath();\n    ctx.arc(it.x, it.y, r + 6, 0, TAU);\n    ctx.fillStyle = 'rgba(74,144,217,.22)';\n    ctx.fill();\n    ctx.beginPath();\n    ctx.arc(it.x, it.y, r, 0, TAU);\n    ctx.fillStyle = '#4A90D9';\n    ctx.fill();\n    ctx.beginPath();\n    ctx.moveTo(it.x, it.y - r*0.55);\n    ctx.lineTo(it.x + r*0.5, it.y - r*0.25);\n    ctx.lineTo(it.x + r*0.5, it.y + r*0.15);\n    ctx.quadraticCurveTo(it.x + r*0.5, it.y + r*0.55, it.x, it.y + r*0.7);\n    ctx.quadraticCurveTo(it.x - r*0.5, it.y + r*0.55, it.x - r*0.5, it.y + r*0.15);\n    ctx.lineTo(it.x - r*0.5, it.y - r*0.25);\n    ctx.closePath();\n    ctx.fillStyle = '#fff';\n    ctx.fill();\n  }\n}\nfunction drawSnake(s, x0, y0, x1, y1){\n  const bb = s.bbox;\n  if(bb.maxX < x0 || bb.minX > x1 || bb.maxY < y0 || bb.minY > y1) return;\n\n  const b = s.body, len = b.length;\n  let lod = 1;\n  if(len > 3000) lod = 12;\n  else if(len > 2000) lod = 8;\n  else if(len > 1000) lod = 6;\n  else if(len > 500) lod = 4;\n  else if(len > 200) lod = 3;\n  else if(len > 60) lod = 2;\n\n  ctx.globalAlpha = s.invincible > 0 ? (0.45 + 0.35*Math.sin(tNow*18)) : 1;\n\n  if(s.boost && len > 1){\n    ctx.beginPath();\n    ctx.moveTo(b[0].x, b[0].y);\n    for(let i=lod; i<len; i+=lod) ctx.lineTo(b[i].x, b[i].y);\n    ctx.strokeStyle = 'rgba(255,255,255,' + (0.28 + 0.15*Math.sin(tNow*20)) + ')';\n    ctx.lineWidth = s.radius * 2 + 5;\n    ctx.lineJoin = 'round';\n    ctx.lineCap = 'round';\n    ctx.stroke();\n  }\n\n  const rBase = s.radius * (lod > 1 ? lod * 0.78 : 1);\n  for(let i = len - 1; i >= 0; i -= lod){\n    const pt = b[i];\n    if(pt.x < x0 || pt.x > x1 || pt.y < y0 || pt.y > y1) continue;\n    ctx.fillStyle = s.color;\n    ctx.beginPath();\n    ctx.arc(pt.x, pt.y, rBase, 0, TAU);\n    ctx.fill();\n  }\n\n  if(s.x > x0-80 && s.x < x1+80 && s.y > y0-80 && s.y < y1+80){\n    const hr = s.headR;\n\n    if(s.isPlayer && s.shield){\n      const pulse = 1 + Math.sin(tNow*4)*0.1;\n      ctx.beginPath();\n      ctx.arc(s.x, s.y, hr*1.9*pulse, 0, TAU);\n      ctx.strokeStyle = 'rgba(74,144,217,.7)';\n      ctx.lineWidth = 2.5;\n      ctx.stroke();\n      ctx.beginPath();\n      ctx.arc(s.x, s.y, hr*2.3*pulse, 0, TAU);\n      ctx.strokeStyle = 'rgba(74,144,217,.3)';\n      ctx.lineWidth = 1.5;\n      ctx.stroke();\n    }\n\n    if(s.isPlayer){\n      const pr = EAT_PULL_BASE + s.radius * EAT_PULL_PER_R;\n      ctx.beginPath();\n      ctx.arc(s.x, s.y, pr, 0, TAU);\n      ctx.strokeStyle = 'rgba(74,144,217,.09)';\n      ctx.lineWidth = 1;\n      ctx.stroke();\n    }\n\n    ctx.beginPath();\n    ctx.arc(s.x, s.y, hr, 0, TAU);\n    ctx.fillStyle = s.color;\n    ctx.fill();\n\n    if(s.isPlayer){\n      ctx.beginPath();\n      ctx.arc(s.x, s.y, hr, 0, TAU);\n      ctx.strokeStyle = 'rgba(74,144,217,.4)';\n      ctx.lineWidth = 1.5;\n      ctx.stroke();\n    }\n\n    const ca = Math.cos(s.angle), sa = Math.sin(s.angle);\n    const px = -sa, py = ca;\n    const eyeOff = hr * 0.42, eyeFwd = hr * 0.32;\n    const eyeR = Math.max(2.2, hr * 0.36);\n    for(let e=1; e>=-1; e-=2){\n      const ex = s.x + ca*eyeFwd + px*eyeOff*e;\n      const ey = s.y + sa*eyeFwd + py*eyeOff*e;\n      ctx.beginPath(); ctx.arc(ex, ey, eyeR, 0, TAU);\n      ctx.fillStyle = '#fff'; ctx.fill();\n      ctx.beginPath();\n      ctx.arc(ex + ca*eyeR*0.35, ey + sa*eyeR*0.35, eyeR*0.55, 0, TAU);\n      ctx.fillStyle = '#1a1a2e'; ctx.fill();\n    }\n\n    const ax = s.x + ca * hr * 1.9;\n    const ay = s.y + sa * hr * 1.9;\n    const aSize = hr * 0.75;\n    ctx.beginPath();\n    ctx.moveTo(ax + ca*aSize, ay + sa*aSize);\n    ctx.lineTo(ax - ca*aSize*0.5 + px*aSize*0.7, ay - sa*aSize*0.5 + py*aSize*0.7);\n    ctx.lineTo(ax - ca*aSize*0.5 - px*aSize*0.7, ay - sa*aSize*0.5 - py*aSize*0.7);\n    ctx.closePath();\n    ctx.fillStyle = 'rgba(74,144,217,.55)';\n    ctx.fill();\n  }\n\n  ctx.globalAlpha = 1;\n}\nfunction drawMinimap(){\n  const S = 110;\n  mctx.setTransform(2, 0, 0, 2, 0, 0);\n  mctx.clearRect(0, 0, S, S);\n  const k = (S/2 - 3) / MAP_R;\n  for(const s of snakes){\n    if(s.dead) continue;\n    mctx.fillStyle = s.isPlayer ? '#ffdd59' : 'rgba(255,255,255,.4)';\n    mctx.beginPath();\n    mctx.arc(S/2 + s.x*k, S/2 + s.y*k, s.isPlayer ? 3 : 1.6, 0, TAU);\n    mctx.fill();\n  }\n  for(const it of items){\n    mctx.beginPath();\n    mctx.arc(S/2 + it.x*k, S/2 + it.y*k, 2.5, 0, TAU);\n    mctx.fillStyle = '#4A90D9';\n    mctx.fill();\n  }\n}\n\nfunction render(){\n  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);\n  ctx.fillStyle = '#0c1322';\n  ctx.fillRect(0, 0, W, H);\n\n  ctx.save();\n  ctx.translate(W/2, H/2);\n  ctx.scale(zoom, zoom);\n  ctx.translate(-cam.x, -cam.y);\n\n  const vw = W / zoom / 2 + 60, vh = H / zoom / 2 + 60;\n  const x0 = cam.x - vw, y0 = cam.y - vh;\n  const x1 = cam.x + vw, y1 = cam.y + vh;\n\n  drawGrid(x0, y0, x1, y1);\n  drawBoundary(x0, y0, x1, y1);\n  drawFoods(x0, y0, x1, y1);\n  drawItems();\n  for(const s of snakes) drawSnake(s, x0, y0, x1, y1);\n\n  ctx.restore();\n  drawMinimap();\n}\n\nfunction updateHUD(){\n  if(!player) return;\n  statLen.textContent = Math.round(player.length);\n  statKill.textContent = player.kills;\n  const sorted = snakes.filter(s => !s.dead).sort((a,b) => b.length - a.length);\n  const rank = sorted.indexOf(player) + 1;\n  statRank.textContent = rank > 0 ? '#' + rank : '#-';\n  if(rank > 0 && rank < player.bestRank) player.bestRank = rank;\n}\n\n/* 输入 */\nconst input = { moveId: null, boostId: null, joyStartX: 0, joyStartY: 0, boost: false, keyBoost: false };\n\nfunction moveJoy(dx, dy){\n  const d = Math.hypot(dx, dy), m = Math.min(d, 45), k = d > 0 ? m/d : 0;\n  joyKnob.style.transform = 'translate(calc(-50% + ' + (dx*k) + 'px), calc(-50% + ' + (dy*k) + 'px))';\n}\nfunction hideJoy(){ joyKnob.style.transform = 'translate(-50%,-50%)'; }\nfunction setDir(dx, dy){\n  if(Math.hypot(dx, dy) > 10 && player && !player.dead)\n    player.targetAngle = Math.atan2(dy, dx);\n}\n\njoyBase.addEventListener('touchstart', e => {\n  e.preventDefault();\n  if(gameState !== 'play') return;\n  const t = e.changedTouches[0];\n  input.moveId = t.identifier;\n  const r = joyBase.getBoundingClientRect();\n  input.joyStartX = r.left + r.width/2;\n  input.joyStartY = r.top + r.height/2;\n  moveJoy(t.clientX - input.joyStartX, t.clientY - input.joyStartY);\n  setDir(t.clientX - input.joyStartX, t.clientY - input.joyStartY);\n}, { passive: false });\n\njoyBase.addEventListener('touchmove', e => {\n  e.preventDefault();\n  for(const t of e.changedTouches){\n    if(t.identifier === input.moveId){\n      const dx = t.clientX - input.joyStartX;\n      const dy = t.clientY - input.joyStartY;\n      moveJoy(dx, dy);\n      setDir(dx, dy);\n    }\n  }\n}, { passive: false });\n\nfunction onJoyEnd(e){\n  for(const t of e.changedTouches){\n    if(t.identifier === input.moveId){\n      input.moveId = null;\n      hideJoy();\n    }\n  }\n}\njoyBase.addEventListener('touchend', onJoyEnd);\njoyBase.addEventListener('touchcancel', onJoyEnd);\n\nboostBtn.addEventListener('touchstart', e => {\n  e.preventDefault();\n  if(gameState !== 'play') return;\n  input.boostId = e.changedTouches[0].identifier;\n  input.boost = true;\n  boostBtn.classList.add('active');\n}, { passive: false });\n\nfunction onBoostEnd(e){\n  for(const t of e.changedTouches){\n    if(t.identifier === input.boostId){\n      input.boostId = null;\n      input.boost = false;\n      boostBtn.classList.remove('active');\n    }\n  }\n}\nboostBtn.addEventListener('touchend', onBoostEnd);\nboostBtn.addEventListener('touchcancel', onBoostEnd);\n\nlet mouseDown = false;\ncv.addEventListener('mousedown', e => {\n  initAudio();\n  if(gameState !== 'play') return;\n  mouseDown = true;\n  input.joyStartX = e.clientX;\n  input.joyStartY = e.clientY;\n  joyBase.style.left = (e.clientX - 55) + 'px';\n  joyBase.style.top = (e.clientY - 55) + 'px';\n  joyBase.style.bottom = 'auto';\n  joyBase.style.display = 'block';\n});\naddEventListener('mousemove', e => {\n  if(!mouseDown || gameState !== 'play') return;\n  const dx = e.clientX - input.joyStartX, dy = e.clientY - input.joyStartY;\n  moveJoy(dx, dy);\n  setDir(dx, dy);\n});\naddEventListener('mouseup', () => {\n  mouseDown = false;\n  hideJoy();\n  joyBase.style.left = '16px';\n  joyBase.style.top = 'auto';\n  joyBase.style.bottom = '24px';\n});\naddEventListener('keydown', e => {\n  if(gameState !== 'play'){\n    if(e.key === ' ' || e.key === 'Enter'){ e.preventDefault(); startGame(); }\n    return;\n  }\n  let a = null;\n  if(e.key === 'ArrowUp' || e.key === 'w' || e.key === 'W') a = -Math.PI/2;\n  else if(e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') a = 0;\n  else if(e.key === 'ArrowDown' || e.key === 's' || e.key === 'S') a = Math.PI/2;\n  else if(e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') a = Math.PI;\n  if(a != null){ e.preventDefault(); if(player) player.targetAngle = a; return; }\n  if(e.key === 'Shift'){ input.boost = true; boostBtn.classList.add('active'); }\n});\naddEventListener('keyup', e => {\n  if(e.key === 'Shift'){ input.boost = false; boostBtn.classList.remove('active'); }\n});\n\nfunction bindStart(el){\n  const handler = e => { e.preventDefault(); initAudio(); startGame(); };\n  el.addEventListener('click', handler);\n  el.addEventListener('touchend', handler);\n}\nbindStart($('startBtn'));\nbindStart($('retryBtn'));\n\nlet lastT = performance.now();\nfunction frame(t){\n  requestAnimationFrame(frame);\n  let dt = (t - lastT) / 1000;\n  lastT = t;\n  if(dt > 0.05) dt = 0.05;\n  if(dt < 0) dt = 0;\n\n  update(dt);\n  render();\n}\n\nsetupMenuWorld();\nrequestAnimationFrame(frame);\n</script>\n</body>\n</html>";
const THUNDER_HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n    <title>雷霆战机 - 移动端</title>\n    <style>\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n            touch-action: none;\n            -webkit-touch-callout: none;\n            -webkit-user-select: none;\n            user-select: none;\n        }\n        \n        body {\n            overflow: hidden;\n            background: #000;\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n        }\n        \n        #gameCanvas {\n            display: block;\n            background: linear-gradient(to bottom, #0a0a2e 0%, #1a1a4e 100%);\n        }\n        \n        #ui {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            pointer-events: none;\n            z-index: 10;\n        }\n        \n        .hp-bar {\n            position: absolute;\n            top: 10px;\n            left: 10px;\n            right: 10px;\n            height: 24px;\n            background: rgba(0,0,0,0.6);\n            border: 2px solid #fff;\n            border-radius: 12px;\n            overflow: hidden;\n        }\n        \n        .hp-fill {\n            height: 100%;\n            background: linear-gradient(90deg, #ff3333, #ff6666);\n            transition: width 0.2s;\n            border-radius: 10px;\n        }\n        \n        .hp-text {\n            position: absolute;\n            top: 50%;\n            left: 50%;\n            transform: translate(-50%, -50%);\n            color: #fff;\n            font-size: 14px;\n            font-weight: bold;\n            text-shadow: 1px 1px 2px #000;\n        }\n        \n        .stats {\n            position: absolute;\n            top: 42px;\n            left: 10px;\n            color: #fff;\n            font-size: 12px;\n            text-shadow: 1px 1px 2px #000;\n            line-height: 1.6;\n        }\n        \n        .turret-info {\n            position: absolute;\n            top: 42px;\n            right: 10px;\n            color: #ffaa00;\n            font-size: 12px;\n            text-align: right;\n            text-shadow: 1px 1px 2px #000;\n        }\n        \n        .boss-warning {\n            position: absolute;\n            top: 50%;\n            left: 50%;\n            transform: translate(-50%, -50%);\n            color: #ff0000;\n            font-size: 48px;\n            font-weight: bold;\n            text-shadow: 0 0 20px #ff0000;\n            opacity: 0;\n            pointer-events: none;\n            z-index: 15;\n            transition: opacity 0.3s;\n        }\n        \n        #startScreen, #gameOverScreen {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            align-items: center;\n            background: rgba(0,0,0,0.88);\n            z-index: 20;\n            pointer-events: auto;\n        }\n        \n        .title {\n            color: #ffdd00;\n            font-size: 36px;\n            font-weight: bold;\n            text-shadow: 0 0 20px #ff6600;\n            margin-bottom: 20px;\n            letter-spacing: 4px;\n        }\n        \n        .btn {\n            padding: 15px 50px;\n            font-size: 20px;\n            color: #fff;\n            background: linear-gradient(180deg, #ff6600, #cc3300);\n            border: none;\n            border-radius: 30px;\n            margin: 10px;\n            cursor: pointer;\n            pointer-events: auto;\n            box-shadow: 0 4px 15px rgba(255, 102, 0, 0.4);\n        }\n        \n        .btn:active {\n            transform: scale(0.95);\n        }\n        \n        .score {\n            color: #fff;\n            font-size: 18px;\n            margin: 10px;\n        }\n        \n        .instructions {\n            color: #aaa;\n            font-size: 13px;\n            text-align: center;\n            margin: 15px 20px;\n            line-height: 1.8;\n            max-width: 320px;\n        }\n        \n        .instructions span {\n            color: #ffdd00;\n        }\n        \n        .hidden {\n            display: none !important;\n        }\n        \n        .damage-flash {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background: rgba(255, 0, 0, 0.3);\n            pointer-events: none;\n            z-index: 15;\n            opacity: 0;\n            transition: opacity 0.1s;\n        }\n    </style>\n</head>\n<body>\n\n<canvas id=\"gameCanvas\"></canvas>\n\n<div id=\"ui\">\n    <div class=\"hp-bar\">\n        <div class=\"hp-fill\" id=\"hpFill\"></div>\n        <div class=\"hp-text\" id=\"hpText\">200 / 200</div>\n    </div>\n    <div class=\"stats\">\n        <div>分数: <span id=\"score\" style=\"color:#ffdd00\">0</span></div>\n        <div>子弹数: <span id=\"bulletCount\" style=\"color:#00ddff\">1</span> / 12</div>\n        <div>子弹速度: <span id=\"bulletSpeed\" style=\"color:#00ddff\">1</span></div>\n        <div>击杀: <span id=\"killCount\" style=\"color:#ff6666\">0</span> / 30</div>\n    </div>\n    <div class=\"turret-info\">\n        <div>炮台: <span id=\"turretCount\" style=\"color:#ffaa00\">0</span> / 5</div>\n        <div id=\"bossInfo\" style=\"color:#ff0000; margin-top:4px;\"></div>\n    </div>\n</div>\n\n<div class=\"boss-warning\" id=\"bossWarning\">BOSS 来袭!</div>\n\n<div class=\"damage-flash\" id=\"damageFlash\"></div>\n\n<div id=\"startScreen\">\n    <div class=\"title\">雷霆战机</div>\n    <div class=\"instructions\">\n        <span>操作：</span>手指拖动控制飞机<br>\n        <span>绿色十字</span> = 回满血(200)<br>\n        <span>蓝色光球</span> = 子弹升级(数量/速度)<br>\n        <span>橙色方块</span> = 炮台道具(底部自动射击)<br>\n        <span>红色警告</span> = 每30击杀出现BOSS<br>\n        血量上限200，每秒自动回2<br>\n        被敌弹击中扣1，撞击扣5\n    </div>\n    <button class=\"btn\" onclick=\"startGame()\">开始游戏</button>\n</div>\n\n<div id=\"gameOverScreen\" class=\"hidden\">\n    <div class=\"title\" style=\"color:#ff3333\">游戏结束</div>\n    <div class=\"score\">最终得分: <span id=\"finalScore\">0</span></div>\n    <div class=\"score\" style=\"font-size:14px; color:#aaa\">击败BOSS: <span id=\"finalBossCount\">0</span></div>\n    <button class=\"btn\" onclick=\"restartGame()\">重新开始</button>\n</div>\n\n<script>\nconst canvas = document.getElementById('gameCanvas');\nconst ctx = canvas.getContext('2d');\n\nfunction resize() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n}\nwindow.addEventListener('resize', resize);\nresize();\n\nlet gameRunning = false;\nlet score = 0;\nlet lastTime = 0;\nlet hpRegenTimer = 0;\nlet gameTime = 0;\n\nconst player = {\n    x: 0, y: 0,\n    width: 40, height: 50,\n    hp: 200, maxHp: 200,\n    bulletCount: 1,\n    bulletSpeed: 1,\n    shootTimer: 0,\n    invincible: 0\n};\n\nlet turrets = [];\nlet turretCount = 0;\nlet bullets = [];\nlet enemyBullets = [];\nlet enemies = [];\nlet items = [];\nlet particles = [];\nlet stars = [];\nlet bosses = [];\n\nlet killCount = 0;\nlet bossCount = 0;\nlet bossWarningTimer = 0;\nlet isBossFight = false;\n\nlet touchX = 0, touchY = 0;\nlet isTouching = false;\n\ncanvas.addEventListener('touchstart', (e) => {\n    e.preventDefault();\n    isTouching = true;\n    const touch = e.touches[0];\n    touchX = touch.clientX;\n    touchY = touch.clientY;\n}, {passive: false});\n\ncanvas.addEventListener('touchmove', (e) => {\n    e.preventDefault();\n    const touch = e.touches[0];\n    touchX = touch.clientX;\n    touchY = touch.clientY;\n}, {passive: false});\n\ncanvas.addEventListener('touchend', (e) => {\n    e.preventDefault();\n    isTouching = false;\n}, {passive: false});\n\ncanvas.addEventListener('mousemove', (e) => {\n    if (e.buttons === 1) {\n        touchX = e.clientX;\n        touchY = e.clientY;\n        isTouching = true;\n    }\n});\ncanvas.addEventListener('mousedown', (e) => {\n    touchX = e.clientX;\n    touchY = e.clientY;\n    isTouching = true;\n});\ncanvas.addEventListener('mouseup', () => isTouching = false);\n\nfunction initStars() {\n    stars = [];\n    for (let i = 0; i < 100; i++) {\n        stars.push({\n            x: Math.random() * canvas.width,\n            y: Math.random() * canvas.height,\n            size: Math.random() * 2 + 0.5,\n            speed: Math.random() * 1.5 + 0.3\n        });\n    }\n}\n\nlet enemySpawnTimer = 0;\nfunction spawnEnemy(dt) {\n    if (isBossFight) return;\n    enemySpawnTimer += dt;\n    \n    const difficulty = Math.min(gameTime / 60, 3);\n    const baseInterval = Math.max(0.3, 1.5 - difficulty * 0.3);\n    const maxEnemies = Math.min(3 + Math.floor(difficulty * 2), 8);\n    \n    if (enemySpawnTimer >= baseInterval && enemies.length < maxEnemies) {\n        enemySpawnTimer = 0;\n        const type = Math.random() < 0.25 ? 'strong' : 'normal';\n        enemies.push({\n            x: Math.random() * (canvas.width - 60) + 30,\n            y: -40,\n            width: type === 'strong' ? 55 : 35,\n            height: type === 'strong' ? 50 : 35,\n            hp: type === 'strong' ? 50 : 2,\n            maxHp: type === 'strong' ? 50 : 2,\n            speed: type === 'strong' ? 1.2 : 2 + Math.random() * 0.5,\n            type: type,\n            shootTimer: 0,\n            shootInterval: Math.max(0.6, 2.5 - difficulty * 0.4),\n            bulletCount: type === 'strong' ? 2 + Math.floor(difficulty) : 1 + Math.floor(difficulty * 0.5)\n        });\n    }\n}\n\nfunction spawnBoss() {\n    if (isBossFight) return;\n    isBossFight = true;\n    bossCount++;\n    const shield = 50 * bossCount;\n    \n    bosses.push({\n        x: canvas.width / 2,\n        y: canvas.height * 0.25,\n        width: 90,\n        height: 80,\n        hp: 20,\n        maxHp: 20,\n        shield: shield,\n        maxShield: shield,\n        speed: 2.5,\n        vx: (Math.random() < 0.5 ? 1 : -1) * 2.5,\n        vy: (Math.random() < 0.5 ? 1 : -1) * 1.5,\n        shootTimer: 0,\n        shootInterval: 0.4,\n        bulletCount: 5 + Math.min(bossCount * 2, 15),\n        phaseTimer: 0,\n        angle: 0\n    });\n    \n    bossWarningTimer = 2.5;\n    const warning = document.getElementById('bossWarning');\n    warning.style.opacity = '1';\n    warning.textContent = `第 ${bossCount} 波 BOSS!`;\n    \n    setTimeout(() => {\n        warning.style.opacity = '0';\n    }, 2000);\n}\n\nlet itemSpawnTimer = 0;\nfunction spawnItem(dt) {\n    itemSpawnTimer += dt;\n    if (itemSpawnTimer >= 8) {\n        itemSpawnTimer = 0;\n        const rand = Math.random();\n        let type;\n        if (rand < 0.33) type = 'heal';\n        else if (rand < 0.66) type = 'bullet';\n        else type = 'turret';\n        \n        items.push({\n            x: Math.random() * (canvas.width - 30) + 15,\n            y: -20,\n            width: 24, height: 24,\n            type: type,\n            speed: 1.5,\n            angle: 0\n        });\n    }\n}\n\nfunction createParticles(x, y, color, count) {\n    for (let i = 0; i < count; i++) {\n        particles.push({\n            x: x, y: y,\n            vx: (Math.random() - 0.5) * 8,\n            vy: (Math.random() - 0.5) * 8,\n            life: 1,\n            color: color,\n            size: Math.random() * 4 + 1\n        });\n    }\n}\n\nfunction checkCollision(a, b) {\n    return a.x - a.width/2 < b.x + b.width/2 &&\n           a.x + a.width/2 > b.x - b.width/2 &&\n           a.y - a.height/2 < b.y + b.height/2 &&\n           a.y + a.height/2 > b.y - b.height/2;\n}\n\nfunction update(dt) {\n    if (!gameRunning) return;\n    gameTime += dt;\n    \n    if (bossWarningTimer > 0) {\n        bossWarningTimer -= dt;\n        if (bossWarningTimer <= 0) {\n            document.getElementById('bossWarning').style.opacity = '0';\n        }\n        return;\n    }\n    \n    if (isTouching) {\n        const dx = touchX - player.x;\n        const dy = touchY - player.y;\n        player.x += dx * 0.15;\n        player.y += dy * 0.15;\n    }\n    \n    player.x = Math.max(player.width/2, Math.min(canvas.width - player.width/2, player.x));\n    player.y = Math.max(player.height/2, Math.min(canvas.height - player.height/2, player.y));\n    \n    if (player.invincible > 0) player.invincible -= dt;\n    \n    hpRegenTimer += dt;\n    if (hpRegenTimer >= 1) {\n        hpRegenTimer -= 1;\n        if (player.hp < player.maxHp) {\n            player.hp = Math.min(player.maxHp, player.hp + 2);\n        }\n    }\n    \n    player.shootTimer += dt;\n    const shootInterval = Math.max(0.08, 0.2 - player.bulletSpeed * 0.015);\n    if (player.shootTimer >= shootInterval) {\n        player.shootTimer = 0;\n        const baseSpeed = 8 + player.bulletSpeed * 0.5;\n        const count = player.bulletCount;\n        const spread = Math.min(70, count * 6);\n        \n        for (let i = 0; i < count; i++) {\n            const angle = -Math.PI/2 + (i - (count-1)/2) * (spread / count) * (Math.PI/180);\n            bullets.push({\n                x: player.x,\n                y: player.y - player.height/2,\n                vx: Math.cos(angle) * baseSpeed,\n                vy: Math.sin(angle) * baseSpeed,\n                width: 4, height: 12,\n                damage: 1\n            });\n        }\n    }\n    \n    turrets.forEach(t => {\n        t.shootTimer += dt;\n        if (t.shootTimer >= 0.35) {\n            t.shootTimer = 0;\n            let nearest = null;\n            let minDist = Infinity;\n            const targets = [...enemies, ...bosses];\n            targets.forEach(e => {\n                const d = Math.hypot(e.x - t.x, e.y - t.y);\n                if (d < minDist) {\n                    minDist = d;\n                    nearest = e;\n                }\n            });\n            \n            const angle = nearest ? \n                Math.atan2(nearest.y - t.y, nearest.x - t.x) : \n                -Math.PI/2;\n            \n            bullets.push({\n                x: t.x,\n                y: t.y - 10,\n                vx: Math.cos(angle) * 10,\n                vy: Math.sin(angle) * 10,\n                width: 5, height: 5,\n                damage: 2,\n                isTurret: true,\n                color: '#ffaa00'\n            });\n        }\n    });\n    \n    bullets = bullets.filter(b => {\n        b.x += b.vx;\n        b.y += b.vy;\n        return b.y > -20 && b.y < canvas.height + 20 && b.x > -20 && b.x < canvas.width + 20;\n    });\n    \n    enemyBullets = enemyBullets.filter(b => {\n        b.x += b.vx;\n        b.y += b.vy;\n        return b.y < canvas.height + 20 && b.y > -20 && b.x > -20 && b.x < canvas.width + 20;\n    });\n    \n    enemies = enemies.filter(e => {\n        e.y += e.speed;\n        e.shootTimer += dt;\n        \n        if (e.shootTimer >= e.shootInterval) {\n            e.shootTimer = 0;\n            const angle = Math.atan2(player.y - e.y, player.x - e.x);\n            const bc = e.bulletCount || 1;\n            for (let i = 0; i < bc; i++) {\n                const spread = (bc - 1) * 0.15;\n                const a = angle + (i - (bc-1)/2) * spread;\n                enemyBullets.push({\n                    x: e.x,\n                    y: e.y + e.height/2,\n                    vx: Math.cos(a) * 4,\n                    vy: Math.sin(a) * 4,\n                    width: 6, height: 6,\n                    damage: 1\n                });\n            }\n        }\n        \n        return e.y < canvas.height + 50 && e.hp > 0;\n    });\n    \n    bosses = bosses.filter(b => {\n        b.phaseTimer += dt;\n        b.angle += dt * 2;\n        \n        b.x += b.vx;\n        b.y += b.vy;\n        \n        const marginX = b.width/2 + 10;\n        const topY = 60;\n        const bottomY = canvas.height * 0.55;\n        \n        if (b.x < marginX || b.x > canvas.width - marginX) b.vx *= -1;\n        if (b.y < topY || b.y > bottomY) b.vy *= -1;\n        \n        b.x = Math.max(marginX, Math.min(canvas.width - marginX, b.x));\n        b.y = Math.max(topY, Math.min(bottomY, b.y));\n        \n        if (b.phaseTimer > 3) {\n            b.phaseTimer = 0;\n            b.vx = (Math.random() < 0.5 ? 1 : -1) * (2 + Math.random() * 2);\n            b.vy = (Math.random() < 0.5 ? 1 : -1) * (1 + Math.random());\n        }\n        \n        b.shootTimer += dt;\n        if (b.shootTimer >= b.shootInterval) {\n            b.shootTimer = 0;\n            const baseAngle = Math.atan2(player.y - b.y, player.x - b.x);\n            \n            let bc = b.bulletCount;\n            let ringCount = 16 + bossCount * 4;\n            let spiralCount = bossCount >= 2 ? 6 : 0;\n            \n            if (bossCount >= 3) {\n                bc *= 2;\n                ringCount *= 2;\n                spiralCount *= 2;\n            }\n            \n            for (let i = 0; i < bc; i++) {\n                const spread = Math.min(1.6, bc * 0.08);\n                const a = baseAngle + (i - (bc-1)/2) * spread;\n                const speed = 5 + Math.min(bossCount * 0.3, 3);\n                enemyBullets.push({\n                    x: b.x,\n                    y: b.y + b.height/2,\n                    vx: Math.cos(a) * speed,\n                    vy: Math.sin(a) * speed,\n                    width: 8, height: 8,\n                    damage: 2,\n                    isBoss: true\n                });\n            }\n            \n            for (let i = 0; i < ringCount; i++) {\n                const a = (Math.PI * 2 / ringCount) * i + b.angle;\n                enemyBullets.push({\n                    x: b.x,\n                    y: b.y,\n                    vx: Math.cos(a) * 3.5,\n                    vy: Math.sin(a) * 3.5,\n                    width: 5, height: 5,\n                    damage: 1,\n                    isBoss: true\n                });\n            }\n            \n            if (spiralCount > 0) {\n                for (let i = 0; i < spiralCount; i++) {\n                    const a = b.angle * 2 + (Math.PI * 2 / spiralCount) * i;\n                    const speed = 4 + Math.sin(b.angle) * 1.5;\n                    enemyBullets.push({\n                        x: b.x,\n                        y: b.y,\n                        vx: Math.cos(a) * speed,\n                        vy: Math.sin(a) * speed,\n                        width: 6, height: 6,\n                        damage: 1,\n                        isBoss: true\n                    });\n                }\n            }\n        }\n        \n        return b.hp > 0;\n    });\n    \n    if (isBossFight && bosses.length === 0) {\n        isBossFight = false;\n        killCount = 0;\n    }\n    \n    items = items.filter(item => {\n        item.y += item.speed;\n        item.angle += dt * 3;\n        return item.y < canvas.height + 30;\n    });\n    \n    particles = particles.filter(p => {\n        p.x += p.vx;\n        p.y += p.vy;\n        p.life -= dt * 2;\n        p.vx *= 0.95;\n        p.vy *= 0.95;\n        return p.life > 0;\n    });\n    \n    stars.forEach(s => {\n        s.y += s.speed;\n        if (s.y > canvas.height) {\n            s.y = 0;\n            s.x = Math.random() * canvas.width;\n        }\n    });\n    \n    bullets.forEach(b => {\n        [...enemies, ...bosses].forEach(e => {\n            if (checkCollision(b, e)) {\n                b.hit = true;\n                if (e.shield && e.shield > 0) {\n                    e.shield -= b.damage;\n                    if (e.shield < 0) {\n                        e.hp += e.shield;\n                        e.shield = 0;\n                    }\n                    createParticles(b.x, b.y, '#4488ff', 3);\n                } else {\n                    e.hp -= b.damage;\n                    createParticles(b.x, b.y, '#ff6600', 4);\n                }\n                \n                if (e.hp <= 0) {\n                    if (bosses.includes(e)) {\n                        score += 200 + bossCount * 50;\n                        createParticles(e.x, e.y, '#ff0000', 30);\n                        createParticles(e.x, e.y, '#ffdd00', 15);\n                    } else {\n                        score += e.type === 'strong' ? 50 : 20;\n                        killCount++;\n                        if (killCount >= 30 && !isBossFight) {\n                            spawnBoss();\n                        }\n                        createParticles(e.x, e.y, '#ff6600', 8);\n                    }\n                }\n            }\n        });\n    });\n    bullets = bullets.filter(b => !b.hit);\n    enemies = enemies.filter(e => e.hp > 0);\n    \n    // ========== 修复：子弹碰撞不再给无敌帧，每颗子弹独立造成伤害 ==========\n    enemyBullets.forEach(b => {\n        if (checkCollision(b, player)) {\n            player.hp -= b.damage;\n            b.hit = true;\n            createParticles(player.x, player.y, '#ff0000', 5);\n            showDamage();\n        }\n    });\n    enemyBullets = enemyBullets.filter(b => !b.hit);\n    \n    // 敌机/BOSS机身撞击保留无敌帧，避免卡身瞬秒\n    enemies.forEach(e => {\n        if (checkCollision(e, player) && player.invincible <= 0) {\n            player.hp -= 5;\n            player.invincible = 1;\n            e.hp = 0;\n            createParticles(player.x, player.y, '#ff0000', 10);\n            showDamage();\n        }\n    });\n    \n    bosses.forEach(b => {\n        if (checkCollision(b, player) && player.invincible <= 0) {\n            player.hp -= 10;\n            player.invincible = 1.5;\n            createParticles(player.x, player.y, '#ff0000', 15);\n            showDamage();\n        }\n    });\n    \n    items = items.filter(item => {\n        if (checkCollision(item, player)) {\n            if (item.type === 'heal') {\n                player.hp = player.maxHp;\n                createParticles(player.x, player.y, '#00ff00', 12);\n            } else if (item.type === 'bullet') {\n                if (player.bulletCount < 12) {\n                    player.bulletCount++;\n                } else {\n                    player.bulletSpeed++;\n                }\n                createParticles(player.x, player.y, '#00ddff', 10);\n            } else if (item.type === 'turret') {\n                if (turretCount < 5) {\n                    turretCount++;\n                    const spacing = canvas.width / (turretCount + 1);\n                    turrets = [];\n                    for (let i = 1; i <= turretCount; i++) {\n                        turrets.push({\n                            x: spacing * i,\n                            y: canvas.height - 30,\n                            shootTimer: 0\n                        });\n                    }\n                }\n                createParticles(player.x, player.y, '#ffaa00', 10);\n            }\n            return false;\n        }\n        return true;\n    });\n    \n    if (player.hp <= 0) {\n        gameOver();\n    }\n    \n    spawnEnemy(dt);\n    spawnItem(dt);\n    updateUI();\n}\n\nfunction showDamage() {\n    const flash = document.getElementById('damageFlash');\n    flash.style.opacity = '1';\n    setTimeout(() => flash.style.opacity = '0', 100);\n}\n\nfunction updateUI() {\n    const hpPercent = Math.max(0, (player.hp / player.maxHp) * 100);\n    document.getElementById('hpFill').style.width = hpPercent + '%';\n    document.getElementById('hpText').textContent = `${Math.ceil(Math.max(0, player.hp))} / ${player.maxHp}`;\n    document.getElementById('score').textContent = score;\n    document.getElementById('bulletCount').textContent = player.bulletCount;\n    document.getElementById('bulletSpeed').textContent = player.bulletSpeed;\n    document.getElementById('turretCount').textContent = turretCount;\n    document.getElementById('killCount').textContent = killCount;\n    \n    const bossInfo = document.getElementById('bossInfo');\n    if (isBossFight && bosses.length > 0) {\n        const b = bosses[0];\n        bossInfo.innerHTML = `BOSS ${bossCount}<br>盾:${Math.ceil(b.shield)} 血:${Math.ceil(b.hp)}`;\n    } else {\n        bossInfo.textContent = '';\n    }\n}\n\nfunction draw() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    \n    ctx.fillStyle = '#fff';\n    stars.forEach(s => {\n        ctx.globalAlpha = Math.random() * 0.5 + 0.3;\n        ctx.beginPath();\n        ctx.arc(s.x, s.y, s.size, 0, Math.PI * 2);\n        ctx.fill();\n    });\n    ctx.globalAlpha = 1;\n    \n    turrets.forEach(t => {\n        ctx.fillStyle = '#444';\n        ctx.fillRect(t.x - 15, t.y - 5, 30, 10);\n        ctx.fillStyle = '#ffaa00';\n        ctx.fillRect(t.x - 4, t.y - 20, 8, 20);\n        ctx.shadowColor = '#ffaa00';\n        ctx.shadowBlur = 10;\n        ctx.fillStyle = '#ffdd00';\n        ctx.beginPath();\n        ctx.arc(t.x, t.y - 20, 5, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.shadowBlur = 0;\n    });\n    \n    items.forEach(item => {\n        ctx.save();\n        ctx.translate(item.x, item.y);\n        ctx.rotate(item.angle);\n        \n        if (item.type === 'heal') {\n            ctx.fillStyle = '#00ff00';\n            ctx.shadowColor = '#00ff00';\n            ctx.shadowBlur = 15;\n            ctx.fillRect(-4, -10, 8, 20);\n            ctx.fillRect(-10, -4, 20, 8);\n            ctx.fillStyle = '#fff';\n            ctx.font = '12px sans-serif';\n            ctx.textAlign = 'center';\n            ctx.fillText('+', 0, 1);\n        } else if (item.type === 'bullet') {\n            ctx.fillStyle = '#00ddff';\n            ctx.shadowColor = '#00ddff';\n            ctx.shadowBlur = 15;\n            ctx.beginPath();\n            ctx.arc(0, 0, 10, 0, Math.PI * 2);\n            ctx.fill();\n            ctx.fillStyle = '#fff';\n            ctx.font = 'bold 11px sans-serif';\n            ctx.textAlign = 'center';\n            ctx.fillText('↑', 0, 3);\n        } else if (item.type === 'turret') {\n            ctx.fillStyle = '#ff8800';\n            ctx.shadowColor = '#ff8800';\n            ctx.shadowBlur = 15;\n            ctx.fillRect(-10, -10, 20, 20);\n            ctx.fillStyle = '#fff';\n            ctx.font = 'bold 10px sans-serif';\n            ctx.textAlign = 'center';\n            ctx.fillText('炮', 0, 3);\n        }\n        \n        ctx.shadowBlur = 0;\n        ctx.restore();\n    });\n    \n    ctx.fillStyle = '#ff4444';\n    enemyBullets.forEach(b => {\n        if (b.isBoss) {\n            ctx.shadowColor = '#ff0000';\n            ctx.shadowBlur = 6;\n        }\n        ctx.beginPath();\n        ctx.arc(b.x, b.y, b.width/2, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.shadowBlur = 0;\n    });\n    \n    bullets.forEach(b => {\n        ctx.fillStyle = b.color || '#00ff88';\n        ctx.shadowColor = b.color || '#00ff88';\n        ctx.shadowBlur = 5;\n        ctx.beginPath();\n        ctx.arc(b.x, b.y, b.width/2, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.shadowBlur = 0;\n    });\n    \n    enemies.forEach(e => {\n        ctx.save();\n        ctx.translate(e.x, e.y);\n        ctx.fillStyle = e.type === 'strong' ? '#aa0000' : '#ff4444';\n        ctx.shadowColor = '#ff0000';\n        ctx.shadowBlur = 8;\n        ctx.beginPath();\n        ctx.moveTo(0, e.height/2);\n        ctx.lineTo(-e.width/2, -e.height/2);\n        ctx.lineTo(0, -e.height/4);\n        ctx.lineTo(e.width/2, -e.height/2);\n        ctx.closePath();\n        ctx.fill();\n        \n        if (e.type === 'strong') {\n            ctx.strokeStyle = '#ffdd00';\n            ctx.lineWidth = 2;\n            ctx.stroke();\n        }\n        \n        if (e.hp < e.maxHp) {\n            ctx.shadowBlur = 0;\n            ctx.fillStyle = '#333';\n            ctx.fillRect(-e.width/2, -e.height/2 - 8, e.width, 4);\n            ctx.fillStyle = '#ff0000';\n            ctx.fillRect(-e.width/2, -e.height/2 - 8, e.width * (e.hp/e.maxHp), 4);\n        }\n        ctx.shadowBlur = 0;\n        ctx.restore();\n    });\n    \n    bosses.forEach(b => {\n        ctx.save();\n        ctx.translate(b.x, b.y);\n        ctx.rotate(Math.sin(b.angle) * 0.1);\n        \n        if (b.shield > 0) {\n            ctx.strokeStyle = '#4488ff';\n            ctx.lineWidth = 4;\n            ctx.shadowColor = '#4488ff';\n            ctx.shadowBlur = 20;\n            ctx.beginPath();\n            ctx.arc(0, 0, b.width/2 + 18, 0, Math.PI * 2);\n            ctx.stroke();\n            ctx.shadowBlur = 0;\n        }\n        \n        ctx.fillStyle = '#660000';\n        ctx.shadowColor = '#ff0000';\n        ctx.shadowBlur = 25;\n        ctx.beginPath();\n        ctx.moveTo(0, -b.height/2);\n        ctx.lineTo(-b.width/2, 0);\n        ctx.lineTo(-b.width/3, b.height/2);\n        ctx.lineTo(0, b.height/3);\n        ctx.lineTo(b.width/3, b.height/2);\n        ctx.lineTo(b.width/2, 0);\n        ctx.closePath();\n        ctx.fill();\n        \n        ctx.fillStyle = '#cc0000';\n        ctx.beginPath();\n        ctx.moveTo(0, -b.height/2 + 12);\n        ctx.lineTo(-b.width/3, 0);\n        ctx.lineTo(0, b.height/4);\n        ctx.lineTo(b.width/3, 0);\n        ctx.closePath();\n        ctx.fill();\n        \n        ctx.fillStyle = '#ffdd00';\n        ctx.beginPath();\n        ctx.arc(0, -5, 10, 0, Math.PI * 2);\n        ctx.fill();\n        \n        ctx.shadowBlur = 0;\n        \n        const barW = b.width + 30;\n        const barH = 7;\n        const barY = -b.height/2 - 30;\n        ctx.fillStyle = '#222';\n        ctx.fillRect(-barW/2, barY, barW, barH);\n        \n        if (b.shield > 0) {\n            ctx.fillStyle = '#4488ff';\n            ctx.fillRect(-barW/2, barY, barW * (b.shield/b.maxShield), barH);\n        }\n        \n        const hpBarWidth = barW * (1 - b.shield/b.maxShield);\n        const hpBarX = -barW/2 + barW * (b.shield/b.maxShield);\n        ctx.fillStyle = '#ff0000';\n        ctx.fillRect(hpBarX, barY, Math.max(0, hpBarWidth * (b.hp/b.maxHp)), barH);\n        \n        ctx.fillStyle = '#fff';\n        ctx.font = 'bold 12px sans-serif';\n        ctx.textAlign = 'center';\n        ctx.fillText(`BOSS ${bossCount}`, 0, barY - 5);\n        \n        ctx.restore();\n    });\n    \n    if (gameRunning) {\n        ctx.save();\n        ctx.translate(player.x, player.y);\n        \n        if (player.invincible > 0 && Math.floor(Date.now() / 100) % 2 === 0) {\n            ctx.globalAlpha = 0.5;\n        }\n        \n        ctx.fillStyle = '#ff6600';\n        ctx.shadowColor = '#ff6600';\n        ctx.shadowBlur = 15;\n        ctx.beginPath();\n        ctx.moveTo(-6, player.height/2);\n        ctx.lineTo(0, player.height/2 + 15 + Math.random() * 10);\n        ctx.lineTo(6, player.height/2);\n        ctx.fill();\n        \n        ctx.fillStyle = '#00aaff';\n        ctx.shadowColor = '#00aaff';\n        ctx.shadowBlur = 10;\n        ctx.beginPath();\n        ctx.moveTo(0, -player.height/2);\n        ctx.lineTo(-player.width/2, player.height/2);\n        ctx.lineTo(0, player.height/3);\n        ctx.lineTo(player.width/2, player.height/2);\n        ctx.closePath();\n        ctx.fill();\n        \n        ctx.fillStyle = '#00ffcc';\n        ctx.beginPath();\n        ctx.arc(0, -5, 6, 0, Math.PI * 2);\n        ctx.fill();\n        \n        ctx.fillStyle = '#ffdd00';\n        ctx.fillRect(-player.width/2 + 3, 5, 4, 10);\n        ctx.fillRect(player.width/2 - 7, 5, 4, 10);\n        \n        ctx.shadowBlur = 0;\n        ctx.globalAlpha = 1;\n        ctx.restore();\n    }\n    \n    particles.forEach(p => {\n        ctx.globalAlpha = p.life;\n        ctx.fillStyle = p.color;\n        ctx.beginPath();\n        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);\n        ctx.fill();\n    });\n    ctx.globalAlpha = 1;\n}\n\nfunction gameLoop(timestamp) {\n    const dt = Math.min((timestamp - lastTime) / 1000, 0.05);\n    lastTime = timestamp;\n    \n    update(dt);\n    draw();\n    \n    requestAnimationFrame(gameLoop);\n}\n\nfunction startGame() {\n    document.getElementById('startScreen').classList.add('hidden');\n    document.getElementById('gameOverScreen').classList.add('hidden');\n    \n    player.x = canvas.width / 2;\n    player.y = canvas.height - 100;\n    player.hp = 200;\n    player.bulletCount = 1;\n    player.bulletSpeed = 1;\n    player.invincible = 0;\n    \n    turrets = [];\n    turretCount = 0;\n    bullets = [];\n    enemyBullets = [];\n    enemies = [];\n    items = [];\n    particles = [];\n    bosses = [];\n    \n    score = 0;\n    killCount = 0;\n    bossCount = 0;\n    isBossFight = false;\n    gameTime = 0;\n    hpRegenTimer = 0;\n    enemySpawnTimer = 0;\n    itemSpawnTimer = 0;\n    bossWarningTimer = 0;\n    \n    touchX = player.x;\n    touchY = player.y;\n    \n    initStars();\n    gameRunning = true;\n    lastTime = performance.now();\n}\n\nfunction gameOver() {\n    gameRunning = false;\n    document.getElementById('finalScore').textContent = score;\n    document.getElementById('finalBossCount').textContent = bossCount;\n    document.getElementById('gameOverScreen').classList.remove('hidden');\n}\n\nfunction restartGame() {\n    startGame();\n}\n\ninitStars();\nrequestAnimationFrame(gameLoop);\n</script>\n\n</body>\n</html>\n";

